#!/usr/bin/env python3
"""Build and verify the reproducible private-runtime payload archive."""

from __future__ import annotations

import argparse
import hashlib
import json
import zipfile
from pathlib import Path, PurePosixPath


FIXED_TIME = (2026, 8, 23, 0, 0, 0)
MANIFEST_NAME = "payload-files.json"


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def relative_files(root: Path) -> list[Path]:
    return sorted(
        (path for path in root.rglob("*") if path.is_file() and path.name != MANIFEST_NAME),
        key=lambda path: path.relative_to(root).as_posix(),
    )


def build(root: Path, output: Path) -> dict[str, object]:
    root = root.resolve()
    output = output.resolve()
    if not root.is_dir():
        raise RuntimeError(f"runtime root is absent: {root}")
    try:
        output.relative_to(root)
    except ValueError:
        pass
    else:
        raise RuntimeError("payload output must be outside the staged runtime root")

    files = relative_files(root)
    manifest = {
        "schema_version": 1,
        "platform": "win-x64",
        "lock_id": "win-x64-2.0.0",
        "files": [
            {
                "path": path.relative_to(root).as_posix(),
                "size": path.stat().st_size,
                "sha256": sha256(path),
            }
            for path in files
        ],
    }
    manifest_path = root / MANIFEST_NAME
    manifest_path.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    archive_files = [manifest_path, *files]
    archive_files.sort(key=lambda path: path.relative_to(root).as_posix())

    output.parent.mkdir(parents=True, exist_ok=True)
    if output.exists():
        output.unlink()
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in archive_files:
            relative = PurePosixPath(path.relative_to(root).as_posix())
            info = zipfile.ZipInfo(str(relative), date_time=FIXED_TIME)
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)

    with zipfile.ZipFile(output) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"payload CRC failed: {bad_member}")
        archived_manifest = json.loads(archive.read(MANIFEST_NAME))
        if archived_manifest != manifest:
            raise RuntimeError("archived payload manifest differs from staging manifest")
        names = set(archive.namelist())
        expected_names = {path.relative_to(root).as_posix() for path in archive_files}
        if names != expected_names:
            raise RuntimeError("payload member set differs from the staged runtime set")

    return {
        "status": "passed",
        "root": str(root),
        "output": str(output),
        "size": output.stat().st_size,
        "sha256": sha256(output),
        "file_count": len(archive_files),
        "manifest": str(manifest_path),
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    try:
        result = build(args.root, args.output)
    except RuntimeError as exc:
        print(json.dumps({"status": "failed", "error": str(exc)}, ensure_ascii=False, indent=2))
        return 5
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""SQLite page-first retrieval index for bounded Agent context packs."""

from __future__ import annotations

from collections import defaultdict
import datetime
import json
import math
from pathlib import Path
import re
import sqlite3
from typing import Any

from .common import CkbError, json_load, json_write, utc_now
from .obsidian import NOTE_DIRECTORIES
from .query_terms import build_fts_query, index_terms, search_terms
from .source_links import ensure_local_openers, source_markdown_link


INDEX_SCHEMA_VERSION = 1
DEFAULT_PAGE_LIMIT = 8


def _tokens(text: str) -> int:
    return math.ceil(len(text.encode("utf-8")) / 3)


def _note_documents(markdown_root: Path) -> list[dict[str, Any]]:
    documents = []
    for directory in NOTE_DIRECTORIES:
        for path in sorted((markdown_root / directory).glob("*.md")):
            text = path.read_text(encoding="utf-8")
            title = text.splitlines()[0].removeprefix("# ").strip() if text else path.stem
            tag_match = re.search(r"#类型/[\w\u3400-\u9fff-]+", text)
            documents.append(
                {
                    "title": title,
                    "tag": tag_match.group(0) if tag_match else "",
                    "file": path.relative_to(markdown_root).as_posix(),
                    "content": text,
                    "links": re.findall(r"\[\[([^\]|#]+)", text),
                }
            )
    return documents


def _projection(output: Path) -> tuple[dict[str, Any], str]:
    """Select the richest completed human projection without requiring Markdown."""
    state_path = output / "state.json"
    if state_path.is_file() and json_load(state_path).get("format") == "logseq-db":
        logseq = output / "logseq-db/projection.json"
        if logseq.is_file():
            return json_load(logseq), "logseq-db"
    markdown = output / "markdown/projection.json"
    if markdown.is_file():
        return json_load(markdown), "markdown"
    logseq = output / "logseq-db/projection.json"
    if logseq.is_file():
        return json_load(logseq), "logseq-db"
    raise CkbError("Agent index requires a finalized Markdown or Logseq DB projection")


def _page_documents(
    output: Path,
    projection: dict[str, Any],
    projection_format: str,
    graph: dict[str, Any],
) -> dict[str, dict[str, Any]]:
    """Return readable page documents for either projection.

    Markdown pages are indexed byte-for-byte.  A DB-only build has no page
    files, so the same reviewed source facts are rendered into a compact
    index-only narrative.  This keeps retrieval format-neutral without adding
    another visible knowledge-base projection.
    """
    page_by_id = {page["id"]: page for page in projection.get("pages", [])}
    title_by_id = {page_id: page["title"] for page_id, page in page_by_id.items()}
    owner_by_entity = projection.get("entity_owner_pages", {})
    entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
    owned: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for entity in graph.get("entities", []):
        owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
        if owner in page_by_id:
            owned[owner].append(entity)

    state = json_load(output / "state.json")
    snapshot = state.get("source_snapshot") or {}
    openers = ensure_local_openers(
        output,
        Path(state["repository"]["root"]),
        Path(snapshot["root"]) if snapshot.get("root") else None,
    )
    documents: dict[str, dict[str, Any]] = {}
    for page_id, page in page_by_id.items():
        entity = entity_by_id.get(page_id)
        if projection_format == "markdown":
            relative = Path("markdown") / page["file"]
            content = (output / relative).read_text(encoding="utf-8")
        else:
            relative = Path("logseq-db/normalized.edn")
            lines = [f"# {page['title']}", "", f"标签：{page.get('tag') or ''}", ""]
            if entity:
                overview = " ".join(
                    value.strip()
                    for value in (str(entity.get("meaning_zh", "")), str(entity.get("role_zh", "")))
                    if value.strip()
                )
                if overview:
                    lines.extend([f"> {overview}", ""])
                if entity.get("change_when_zh"):
                    lines.extend(["## 什么时候需要修改", "", str(entity["change_when_zh"]), ""])
                if entity.get("path") and entity.get("range"):
                    lines.extend(
                        [
                            "## 源码位置",
                            "",
                            source_markdown_link(
                                openers,
                                str(entity["path"]),
                                int(entity["range"]["start_line"]),
                                int(entity["range"]["end_line"]),
                            ),
                            "",
                        ]
                    )
            else:
                lines.extend(["> 这是由相关类、函数和辅助实现组成的职责导航页。", ""])
            appendix = [item for item in owned.get(page_id, []) if item.get("classification") == "appendix"]
            if appendix:
                lines.extend(["## 内部细节", ""])
                for item in sorted(appendix, key=lambda value: (value.get("path", ""), value.get("range", {}).get("start_line", 0), value.get("qualified_name", ""))):
                    lines.append(f"- `{item.get('qualified_name') or item.get('name')}`：{item.get('description_zh') or item.get('role_zh') or '承担局部辅助处理。'}")
                lines.append("")
            neighbors = []
            for link in projection.get("links", []):
                if link.get("source") == page_id and link.get("target") in title_by_id:
                    neighbors.append(title_by_id[link["target"]])
                elif link.get("target") == page_id and link.get("source") in title_by_id:
                    neighbors.append(title_by_id[link["source"]])
            if neighbors:
                lines.extend(["## 相关代码", "", *[f"- [[{title}]]" for title in sorted(set(neighbors))], ""])
            content = "\n".join(lines).rstrip() + "\n"
        summary = next(
            (
                line.removeprefix("> ").strip()
                for line in content.splitlines()
                if line.startswith("> ") and line.removeprefix("> ").strip()
            ),
            page["title"],
        )
        source_range = entity.get("range", {}) if entity else {}
        documents[page_id] = {
            "content": content,
            "summary": summary,
            "page_file": relative.as_posix(),
            "source_path": entity.get("path") if entity else None,
            "start_line": source_range.get("start_line"),
            "end_line": source_range.get("end_line"),
        }
    return documents


def build_agent_index(output: Path) -> dict[str, Any]:
    markdown_root = output / "markdown"
    projection, projection_format = _projection(output)
    graph = json_load(output / "graph.json")
    pages = projection.get("pages", [])
    documents = _page_documents(output, projection, projection_format, graph)
    page_by_id = {page["id"]: page for page in pages}
    owner_by_entity = projection.get("entity_owner_pages", {})
    symbols_by_page: dict[str, list[str]] = defaultdict(list)
    for entity in graph.get("entities", []):
        owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
        if owner in page_by_id:
            for value in (entity.get("name"), entity.get("qualified_name")):
                if value:
                    symbols_by_page[owner].append(str(value))
    index = output / "agent-index.sqlite"
    temporary = output / "agent-index.sqlite.tmp"
    temporary.unlink(missing_ok=True)
    connection = sqlite3.connect(temporary)
    try:
        connection.executescript(
            """
            PRAGMA foreign_keys=ON;
            CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
            CREATE TABLE pages(
                page_id TEXT PRIMARY KEY,
                title TEXT NOT NULL UNIQUE,
                page_type TEXT NOT NULL,
                tag TEXT NOT NULL,
                page_file TEXT NOT NULL,
                source_path TEXT,
                start_line INTEGER,
                end_line INTEGER,
                summary TEXT NOT NULL,
                content TEXT NOT NULL,
                token_estimate INTEGER NOT NULL
            );
            CREATE TABLE symbols(
                symbol TEXT NOT NULL,
                qualified_name TEXT NOT NULL,
                owner_page_id TEXT NOT NULL REFERENCES pages(page_id),
                source_path TEXT,
                start_line INTEGER,
                end_line INTEGER
            );
            CREATE INDEX symbols_name ON symbols(symbol COLLATE NOCASE);
            CREATE INDEX symbols_qname ON symbols(qualified_name COLLATE NOCASE);
            CREATE TABLE edges(
                source_page_id TEXT NOT NULL REFERENCES pages(page_id),
                target_page_id TEXT NOT NULL REFERENCES pages(page_id),
                relation TEXT NOT NULL,
                weight REAL NOT NULL,
                PRIMARY KEY(source_page_id,target_page_id,relation)
            );
            CREATE INDEX edges_target ON edges(target_page_id);
            CREATE TABLE terms(
                term TEXT NOT NULL,
                page_id TEXT NOT NULL REFERENCES pages(page_id),
                weight REAL NOT NULL,
                PRIMARY KEY(term,page_id)
            );
            CREATE INDEX terms_term ON terms(term);
            CREATE TABLE notes(
                note_title TEXT PRIMARY KEY,
                tag TEXT NOT NULL,
                note_file TEXT NOT NULL,
                content TEXT NOT NULL,
                token_estimate INTEGER NOT NULL
            );
            CREATE TABLE note_links(
                note_title TEXT NOT NULL REFERENCES notes(note_title),
                page_title TEXT NOT NULL,
                PRIMARY KEY(note_title,page_title)
            );
            CREATE VIRTUAL TABLE page_fts USING fts5(
                page_id UNINDEXED,
                title,
                summary,
                symbols,
                source_path,
                tokenize='trigram'
            );
            CREATE VIRTUAL TABLE note_fts USING fts5(
                note_title UNINDEXED,
                title,
                content,
                tokenize='trigram'
            );
            """
        )
        connection.executemany(
            "INSERT INTO meta(key,value) VALUES(?,?)",
            [
                ("schema_version", str(INDEX_SCHEMA_VERSION)),
                ("status", "ready"),
                ("built_at_utc", utc_now()),
                ("page_count", str(len(pages))),
                ("projection_format", projection_format),
            ],
        )
        entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
        for page in pages:
            document = documents[page["id"]]
            content = document["content"]
            summary = document["summary"]
            source_path = document["source_path"]
            symbols = sorted(set(symbols_by_page.get(page["id"], [])))
            connection.execute(
                "INSERT INTO pages VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (
                    page["id"],
                    page["title"],
                    page["page_type"],
                    page.get("tag") or "",
                    document["page_file"],
                    source_path,
                    document["start_line"],
                    document["end_line"],
                    summary,
                    content,
                    _tokens(content),
                ),
            )
            connection.execute(
                "INSERT INTO page_fts(page_id,title,summary,symbols,source_path) VALUES(?,?,?,?,?)",
                (page["id"], page["title"], summary, " ".join(symbols), source_path or ""),
            )
            weighted_terms: dict[str, float] = {}
            for value, weight in ((page["title"], 8.0), (" ".join(symbols), 6.0), (summary, 3.0), (source_path or "", 2.0)):
                for term in index_terms(value):
                    weighted_terms[term] = max(weighted_terms.get(term, 0.0), weight)
            connection.executemany(
                "INSERT INTO terms(term,page_id,weight) VALUES(?,?,?)",
                [(term, page["id"], weight) for term, weight in sorted(weighted_terms.items())],
            )
        for entity in graph.get("entities", []):
            owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
            if owner not in page_by_id:
                continue
            source_range = entity.get("range", {})
            connection.execute(
                "INSERT INTO symbols VALUES(?,?,?,?,?,?)",
                (
                    str(entity.get("name") or entity.get("qualified_name") or ""),
                    str(entity.get("qualified_name") or entity.get("name") or ""),
                    owner,
                    entity.get("path"),
                    source_range.get("start_line"),
                    source_range.get("end_line"),
                ),
            )
        relation_weight = {"tested-by": 1.4, "calls": 1.3, "invokes": 1.3, "depends-on": 1.2, "uses": 1.1, "contains": 0.8}
        for link in projection.get("links", []):
            if link["source"] not in page_by_id or link["target"] not in page_by_id:
                continue
            connection.execute(
                "INSERT OR REPLACE INTO edges VALUES(?,?,?,?)",
                (link["source"], link["target"], link["type"], relation_weight.get(link["type"], 1.0)),
            )
        for note in _note_documents(markdown_root) if projection_format == "markdown" else []:
            connection.execute(
                "INSERT INTO notes VALUES(?,?,?,?,?)",
                (note["title"], note["tag"], note["file"], note["content"], _tokens(note["content"])),
            )
            connection.execute(
                "INSERT INTO note_fts(note_title,title,content) VALUES(?,?,?)",
                (note["title"], note["title"], note["content"]),
            )
            for title in note["links"]:
                connection.execute("INSERT OR IGNORE INTO note_links VALUES(?,?)", (note["title"], title))
        connection.commit()
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        if integrity != "ok" or foreign_keys:
            raise CkbError(f"Agent index integrity failed: integrity={integrity}; foreign_keys={foreign_keys}")
    finally:
        connection.close()
    temporary.replace(index)
    return audit_agent_index(output)


def audit_agent_index(output: Path) -> dict[str, Any]:
    index = output / "agent-index.sqlite"
    if not index.is_file():
        return {"schema_version": 1, "status": "failed", "errors": [{"reason": "agent-index-missing"}]}
    projection, projection_format = _projection(output)
    expected_notes = len(_note_documents(output / "markdown")) if projection_format == "markdown" else 0
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    try:
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        counts = {
            "pages": connection.execute("SELECT count(*) FROM pages").fetchone()[0],
            "symbols": connection.execute("SELECT count(*) FROM symbols").fetchone()[0],
            "edges": connection.execute("SELECT count(*) FROM edges").fetchone()[0],
            "terms": connection.execute("SELECT count(*) FROM terms").fetchone()[0],
            "notes": connection.execute("SELECT count(*) FROM notes").fetchone()[0],
        }
        meta = dict(connection.execute("SELECT key,value FROM meta").fetchall())
        forbidden_columns = []
        for table in ("pages", "symbols", "edges", "notes", "meta"):
            for row in connection.execute(f"PRAGMA table_info({table})"):
                if "hash" in str(row[1]).casefold():
                    forbidden_columns.append(f"{table}.{row[1]}")
    finally:
        connection.close()
    errors = []
    if integrity != "ok":
        errors.append({"reason": "sqlite-integrity", "detail": integrity})
    if foreign_keys:
        errors.append({"reason": "foreign-key-errors", "detail": foreign_keys})
    if counts["pages"] != len(projection.get("pages", [])):
        errors.append({"reason": "page-count-mismatch", "actual": counts["pages"], "expected": len(projection.get("pages", []))})
    if counts["notes"] != expected_notes:
        errors.append({"reason": "note-count-mismatch", "actual": counts["notes"], "expected": expected_notes})
    if forbidden_columns:
        errors.append({"reason": "new-index-hash-column-present", "columns": forbidden_columns})
    if meta.get("projection_format") != projection_format:
        errors.append({"reason": "projection-format-mismatch", "actual": meta.get("projection_format"), "expected": projection_format})
    return {
        "schema_version": INDEX_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "path": str(index.resolve()),
        "integrity": integrity,
        "counts": counts,
        "projection_format": projection_format,
        "errors": errors,
    }


def _agent_index_ready(output: Path) -> None:
    index = output / "agent-index.sqlite"
    if not index.is_file():
        raise CkbError("Agent index is missing; run reindex or finalize")
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    try:
        meta = dict(connection.execute("SELECT key,value FROM meta").fetchall())
    except sqlite3.DatabaseError as exc:
        raise CkbError(f"Agent index metadata is unavailable: {exc}") from exc
    finally:
        connection.close()
    if meta.get("status") != "ready" or meta.get("schema_version") != str(INDEX_SCHEMA_VERSION):
        raise CkbError(f"Agent index metadata is incompatible: {meta}")


def _fts_query(question: str) -> str | None:
    return build_fts_query(question, 12)


def _next_pack_path(output: Path) -> tuple[Path, Path]:
    directory = output / "agent-packs"
    directory.mkdir(parents=True, exist_ok=True)
    prefix = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d-%H%M%S-%f")
    counter = 1
    while True:
        stem = f"pack-{prefix}-{counter:02d}"
        markdown = directory / f"{stem}.md"
        record = directory / f"{stem}.json"
        if not markdown.exists() and not record.exists():
            return markdown, record
        counter += 1


def retrieve(output: Path, question: str, budget: int = 1500, page_limit: int = DEFAULT_PAGE_LIMIT) -> dict[str, Any]:
    if budget < 200:
        raise CkbError("retrieve budget must be at least 200")
    if page_limit < 1 or page_limit > 32:
        raise CkbError("retrieve page limit must be in [1, 32]")
    _agent_index_ready(output)
    index = output / "agent-index.sqlite"
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    scores: dict[str, float] = defaultdict(float)
    reasons: dict[str, list[str]] = defaultdict(list)
    terms = search_terms(question)
    try:
        for row in connection.execute("SELECT page_id,title FROM pages WHERE title=? COLLATE NOCASE", (question,)):
            scores[row["page_id"]] += 160
            reasons[row["page_id"]].append("页面标题精确匹配")
        for term in terms:
            for row in connection.execute(
                "SELECT owner_page_id,symbol,qualified_name FROM symbols WHERE symbol=? COLLATE NOCASE OR qualified_name=? COLLATE NOCASE LIMIT 20",
                (term, term),
            ):
                scores[row["owner_page_id"]] += 120
                reasons[row["owner_page_id"]].append(f"符号精确匹配：{row['qualified_name']}")
            for row in connection.execute("SELECT page_id,weight FROM terms WHERE term=? LIMIT 50", (term,)):
                scores[row["page_id"]] += float(row["weight"])
                reasons[row["page_id"]].append(f"索引词匹配：{term}")
        fts = _fts_query(question)
        if fts:
            for row in connection.execute(
                "SELECT page_id,bm25(page_fts,8.0,3.0,6.0,2.0) AS rank FROM page_fts WHERE page_fts MATCH ? ORDER BY rank LIMIT 30",
                (fts,),
            ):
                scores[row["page_id"]] += 40.0 / (1.0 + abs(float(row["rank"])))
                reasons[row["page_id"]].append("全文索引匹配")
        if not scores:
            return {
                "schema_version": INDEX_SCHEMA_VERSION,
                "status": "needs-grep",
                "question": question,
                "budget": budget,
                "grep_terms": terms[:12],
                "reason": "Agent index found no page candidate",
            }
        seeds = [page_id for page_id, _score in sorted(scores.items(), key=lambda item: (-item[1], item[0]))[:3]]
        for seed in seeds:
            for row in connection.execute(
                "SELECT source_page_id,target_page_id,relation,weight FROM edges WHERE source_page_id=? OR target_page_id=?",
                (seed, seed),
            ):
                neighbor = row["target_page_id"] if row["source_page_id"] == seed else row["source_page_id"]
                scores[neighbor] += 18.0 * float(row["weight"])
                reasons[neighbor].append(f"与高相关页面一跳关联：{row['relation']}")
        ordered = sorted(scores, key=lambda page_id: (-scores[page_id], page_id))
        pack_path, record_path = _next_pack_path(output)
        header = ["# Agent 阅读包", "", f"问题：{question}", "", "按顺序阅读以下页面；源码链接可以直接打开对应位置。", ""]
        selected = []
        pack = "\n".join(header)
        for page_id in ordered:
            if len(selected) >= page_limit:
                break
            row = connection.execute("SELECT * FROM pages WHERE page_id=?", (page_id,)).fetchone()
            if row is None:
                continue
            reason_text = "；".join(dict.fromkeys(reasons[page_id]))
            block = (
                f"## {row['title']}\n\n"
                f"选择原因：{reason_text}\n\n"
                f"知识页：`{row['page_file']}`\n\n"
                f"{row['content'].strip()}\n\n"
            )
            candidate = pack + block
            if _tokens(candidate) > budget:
                if selected:
                    continue
                allowed_bytes = max(0, budget * 3 - len((pack + f"## {row['title']}\n\n选择原因：{reason_text}\n\n").encode("utf-8")) - 80)
                content_bytes = row["content"].encode("utf-8")[:allowed_bytes]
                while True:
                    try:
                        truncated = content_bytes.decode("utf-8")
                        break
                    except UnicodeDecodeError as exc:
                        content_bytes = content_bytes[: exc.start]
                block = f"## {row['title']}\n\n选择原因：{reason_text}\n\n{truncated.rstrip()}\n\n> 页面内容已按预算截断。\n\n"
                candidate = pack + block
            if _tokens(candidate) <= budget:
                pack = candidate
                selected.append(
                    {
                        "page_id": page_id,
                        "title": row["title"],
                        "page_file": str((output / row["page_file"]).resolve()),
                        "tag": row["tag"],
                        "source_path": row["source_path"],
                        "start_line": row["start_line"],
                        "end_line": row["end_line"],
                        "page_tokens": row["token_estimate"],
                        "score": round(scores[page_id], 6),
                        "reasons": list(dict.fromkeys(reasons[page_id])),
                    }
                )
        note_rows = []
        if fts:
            for row in connection.execute(
                "SELECT note_title,bm25(note_fts,8.0,2.0) AS rank FROM note_fts WHERE note_fts MATCH ? ORDER BY rank LIMIT 5",
                (fts,),
            ):
                note = connection.execute("SELECT * FROM notes WHERE note_title=?", (row["note_title"],)).fetchone()
                if note:
                    note_rows.append({"title": note["note_title"], "file": str((output / "markdown" / note["note_file"]).resolve()), "tag": note["tag"]})
    finally:
        connection.close()
    if not selected:
        raise CkbError("retrieve budget is too small for the highest-ranked page")
    pack_path.write_text(pack.rstrip() + "\n", encoding="utf-8", newline="\n")
    result = {
        "schema_version": INDEX_SCHEMA_VERSION,
        "status": "passed",
        "question": question,
        "budget": budget,
        "estimated_tokens": _tokens(pack),
        "selected_pages": selected,
        "related_notes": note_rows,
        "pack": str(pack_path.resolve()),
        "record": str(record_path.resolve()),
        "retrieval": "sqlite-exact-terms-fts5-trigram-plus-one-hop-graph",
        "grep_fallback_required": False,
    }
    json_write(record_path, result)
    return result

"""Persistent cross-Harness instructions and deterministic maintenance checks."""

from __future__ import annotations

import re
import sqlite3
import sys
from pathlib import Path
from typing import Any

from .common import AuditError, CkbError, json_load, json_write, path_inside, safe_title
from .feedback import audit_feedback, prepare_feedback_store
from .obsidian import NOTE_DIRECTORIES
from .workspace_notes import DIRECTORY_BY_KIND, audit_notes
from .work_record_index import audit_work_record_index


AGENT_PROTOCOL_SCHEMA_VERSION = 1
AGENT_PROTOCOL_VERSION = "1.5.0"
POLICY_BEGIN = "<!-- CKB-AGENT-PROTOCOL:BEGIN -->"
POLICY_END = "<!-- CKB-AGENT-PROTOCOL:END -->"
INTERNAL_ROOT_NAMES = ("output", "markdown", "human")
ADAPTER_PATHS = {
    "agents": Path("AGENTS.md"),
    "claude": Path("CLAUDE.md"),
    "gemini": Path("GEMINI.md"),
    "copilot": Path(".github/copilot-instructions.md"),
    "cursor": Path(".cursor/rules/code-knowledge-builder.mdc"),
}
OBSIDIAN_IGNORES = ("AGENTS.md", "CLAUDE.md", "GEMINI.md", ".github/", ".cursor/")
OBSIDIAN_HIDE_CSS = """.nav-file-title[data-path=\"AGENTS.md\"],
.nav-file-title[data-path=\"CLAUDE.md\"],
.nav-file-title[data-path=\"GEMINI.md\"] { display: none; }"""


def _default_python() -> Path:
    return Path(sys.executable).resolve()


def _default_ckb() -> Path:
    return (Path(__file__).resolve().parents[1] / "ckb.py").resolve()


def _single_quote(value: str) -> str:
    return value.replace("'", "''")


def _command_examples(output: Path, python: Path, ckb: Path) -> dict[str, str]:
    py = _single_quote(str(python))
    cli = _single_quote(str(ckb))
    out = _single_quote(str(output.resolve()))
    prefix = f"& '{py}' '{cli}'"
    return {
        "brief": f'{prefix} brief --out \'{out}\' "QUESTION" --budget 1800 --max-pages 8 --profile fast',
        "retrieve": f'{prefix} retrieve --out \'{out}\' "QUESTION" --budget 1800 --max-pages 8 --profile fast',
        "precise": f'{prefix} retrieve --out \'{out}\' "QUESTION" --budget 3000 --max-pages 12 --profile precise',
        "entity": f'{prefix} entity --out \'{out}\' "SYMBOL"',
        "neighbors": f'{prefix} neighbors --out \'{out}\' "SYMBOL" --depth 2',
        "source": f'{prefix} source --out \'{out}\' "SYMBOL" --context-lines 3',
        "record": f"{prefix} record --out '{out}' --kind analysis --title 'TITLE' --body 'BODY.md' --from-pack 'PACK.json'",
        "append": f"{prefix} record --out '{out}' --kind analysis --title 'EXISTING_TITLE' --body 'BODY.md' --from-pack 'PACK.json' --append",
        "feedback_list": f"{prefix} feedback list --out '{out}' --status open",
        "feedback_locate": f"{prefix} feedback locate --out '{out}' --feedback 'FEEDBACK_ID'",
        "feedback_audit": f"{prefix} feedback audit --out '{out}'",
        "check": f"{prefix} agent-policy check --out '{out}'",
        "maintain": f"{prefix} maintain --out '{out}'",
        "capabilities": f"{prefix} capabilities --format json",
        "reference_list": f"{prefix} reference list --out '{out}' --status all",
        "reference_audit": f"{prefix} reference audit --out '{out}'",
        "gaps_list": f"{prefix} gaps list --out '{out}' --status open",
        "gaps_audit": f"{prefix} gaps audit --out '{out}'",
    }


def _protocol_text(output: Path, repository: str, python: Path, ckb: Path) -> str:
    commands = _command_examples(output, python, ckb)
    return f"""# Code Knowledge Builder Agent 工作协议

本文件是自动加载的项目级工作指令，不是知识页面。凡是读取、解释或修改本知识库及其对应源码的智能体，都必须遵循以下流程；无需用户再次点名 Skill。

## 绑定范围

- 知识库：`{output.resolve()}`
- 源码仓库：`{repository}`
- 命令入口：`{ckb}`

## 先检索，后读源码

1. 回答架构、实现、定位或修改问题前，先执行紧凑阅读入口。它在一个小 JSON 中返回开放反馈数、Agent pack、完整检索 record 和固定阅读入口，不把候选实体、词项和得分展开到首轮上下文：

```powershell
{commands['brief']}
```

2. 若 `open_feedback` 大于零，再列出开放反馈；任务涉及其目标页时按 `error`、`warn`、`suggest`、`info` 的固定优先级处理：

```powershell
{commands['feedback_list']}
```

3. 先阅读 `brief` 返回的预算化 Agent pack；完整候选与得分仍保存在 `record`。再按 pack 使用 `entity`、`neighbors`、`source` 或 `changes`；复杂跨模块问题才切换 `precise`。
4. 只有检索明确返回 `needs-source-read`，或返回了需要核实的精确路径和范围时，才使用窄范围源码读取。`grep`、全仓文件遍历和整库页面加载只作为这一分支的补充手段，不得替代首轮 SQLite 检索。
5. 人类需要查找已有分析、变更或实验时，从 `RECORDS.md` 按任务目的浏览；查找已审阅外部资料时从 `REFERENCES.md` 浏览。两个导览都由完整集合生成，不允许为单个查询手工挑选页面。

## 受控维护

1. `human/pages`、`markdown/pages`、`human/references`、`markdown/references`、`INDEX.md`、`WIKI.md`、`REFERENCES.md`、投影清单和 SQLite 文件属于生成器管理内容，不直接编辑。
2. 可复用分析、修改原因、踩坑和实验只通过 `record` 写入；正文使用简体中文，并通过 `--from-pack`、`--from-query` 或唯一 `--link` 回链至少一个知识页。
3. 创建分析页的标准命令：

```powershell
{commands['record']}
```

4. 更新已有人工笔记时使用同标题和 `--append`。Hook 仅采集会话与修改事件，并在 Agent 审核后新建会话页或修改页；其他已有页面只在任务明确要求时执行显式追加，不随每轮对话扩散更新。
5. 外部文本资料只通过 `reference ingest/review/audit/rollback` 进入独立参考层。Agent 必须重新打开归档原文，逐项提交精确行范围、原文文本、中文主张和中文来源核对；参考资料不成为代码实体。
6. 检索证据不足、来源冲突或反馈需要暂缓时，使用 `gaps create` 把中文待验证说明和现有证据路径写入机器缺口层。缺口不属于已确认事实，也不为每项缺口创建页面；开始新任务时可执行：

```powershell
{commands['gaps_list']}
```

7. 人工反馈通过 `feedback create` 进入带行范围和文本窗口的收件箱。处理前先执行：

```powershell
{commands['feedback_locate']}
```

生成器管理页面仍不直接编辑；采纳或部分采纳时先修改来源、生成规则或通过 `record` 写入落实记录，再用 `feedback resolve` 归档。拒绝必须写明中文理由；暂缓记录继续留在开放列表。反馈记录不删除。
8. 结束实质任务前执行聚合维护门；它统一检查反馈、Agent Policy、工作记录、参考资料、研究缺口、机器操作日志、人类可读性、机器知识库和兼容索引，并且不创建知识页面：

```powershell
{commands['maintain']}
```

只有协议文件、中文与链接规则、human/markdown 镜像、笔记元数据以及两个 SQLite 索引全部一致时，才报告知识库维护完成。失败时根据 `failed_checks` 运行窄范围审计，修复对应笔记或重新执行 `record`/`reindex`，再复查。

## 最小上下文原则

- 优先顺序固定为：`brief fast` → Agent pack → `entity/neighbors/source/changes` → 返回路径的窄范围读取。
- 不预先加载整个模块、整个 vault 或完整关系图。
- 页面正文保持面向人类的简体中文叙述；英文仅保留专有名词、API、类型、函数、变量、命令和路径。
"""


def _adapter_texts(protocol: str) -> dict[str, str]:
    return {
        "agents": protocol,
        "claude": "# Claude Code 项目指令\n\n@./AGENTS.md\n",
        "gemini": "# Gemini CLI 项目指令\n\n@./AGENTS.md\n",
        "copilot": protocol,
        "cursor": (
            "---\n"
            "description: Code Knowledge Builder 检索与维护协议\n"
            "globs:\n"
            "alwaysApply: true\n"
            "---\n\n"
            + protocol
        ),
    }


def _managed_block(text: str) -> str:
    return f"{POLICY_BEGIN}\n{text.rstrip()}\n{POLICY_END}\n"


def _replace_managed_block(existing: str, block: str) -> str:
    pattern = re.compile(re.escape(POLICY_BEGIN) + r".*?" + re.escape(POLICY_END) + r"\n?", re.DOTALL)
    matches = pattern.findall(existing)
    if len(matches) > 1:
        raise CkbError("workspace instruction file contains duplicate CKB Agent protocol blocks")
    if matches:
        return pattern.sub(lambda _match: block, existing, count=1)
    if not existing.strip():
        return block
    return existing.rstrip() + "\n\n" + block


def _instruction_roots(output: Path) -> dict[str, Path]:
    roots = {"output": output.resolve()}
    for name in ("markdown", "human"):
        path = (output / name).resolve()
        if path.is_dir():
            roots[name] = path
    return roots


def _write_exact_root(root: Path, texts: dict[str, str]) -> list[str]:
    written: list[str] = []
    for key, relative in ADAPTER_PATHS.items():
        target = root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(texts[key], encoding="utf-8", newline="\n")
        written.append(relative.as_posix())
    return written


def _update_markdown_ownership(output: Path) -> None:
    ownership_path = output / "markdown/.ckb-generated-files.json"
    if not ownership_path.is_file():
        return
    ownership = json_load(ownership_path)
    ownership["files"] = sorted(set(ownership.get("files", [])) | {path.as_posix() for path in ADAPTER_PATHS.values()})
    json_write(ownership_path, ownership)


def _hide_protocol_files(output: Path) -> None:
    """Keep Harness adapters out of the human Obsidian navigation surface."""
    for name in ("markdown", "human"):
        root = output / name
        app_path = root / ".obsidian/app.json"
        if app_path.is_file():
            app = json_load(app_path)
            app["userIgnoreFilters"] = list(dict.fromkeys([*app.get("userIgnoreFilters", []), *OBSIDIAN_IGNORES]))
            json_write(app_path, app)
        css_path = root / ".obsidian/snippets/ckb.css"
        if css_path.is_file():
            css = css_path.read_text(encoding="utf-8")
            if OBSIDIAN_HIDE_CSS not in css:
                css_path.write_text(css.rstrip() + "\n" + OBSIDIAN_HIDE_CSS + "\n", encoding="utf-8", newline="\n")


def _load_record(output: Path) -> dict[str, Any] | None:
    path = output / "workspace-meta/agent-protocol.json"
    return json_load(path) if path.is_file() else None


def _resolve_runtime(record: dict[str, Any] | None, python: Path | None, ckb: Path | None) -> tuple[Path, Path]:
    python_path = python or (Path(str(record["python"])) if record and record.get("python") else _default_python())
    ckb_path = ckb or (Path(str(record["ckb"])) if record and record.get("ckb") else _default_ckb())
    if not python_path.is_file():
        raise CkbError(f"Agent protocol Python executable is missing: {python_path}")
    if not ckb_path.is_file():
        raise CkbError(f"Agent protocol CKB entrypoint is missing: {ckb_path}")
    return python_path.resolve(), ckb_path.resolve()


def _workspace_root_allowed(root: Path, output: Path, repository: str) -> bool:
    if path_inside(output.resolve(), root.resolve()):
        return True
    repo = Path(repository)
    return repo.is_absolute() and path_inside(repo.resolve(), root.resolve())


def _write_workspace_root(root: Path, texts: dict[str, str]) -> dict[str, Any]:
    files: list[dict[str, Any]] = []
    for key, relative in ADAPTER_PATHS.items():
        target = root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        existing = target.read_text(encoding="utf-8-sig") if target.is_file() else ""
        block = _managed_block(texts[key])
        updated = _replace_managed_block(existing, block)
        target.write_text(updated, encoding="utf-8", newline="\n")
        files.append({"path": str(target.resolve()), "relative_path": relative.as_posix(), "created": not bool(existing)})
    return {"root": str(root.resolve()), "files": files}


def project_agent_protocol(
    output: Path,
    *,
    python: Path | None = None,
    ckb: Path | None = None,
) -> dict[str, Any]:
    """Project exact protocol adapters into the knowledge output roots."""
    output = output.resolve()
    state_path = output / "state.json"
    if not state_path.is_file():
        raise CkbError(f"knowledge build state is missing: {state_path}")
    state = json_load(state_path)
    repository = str(state["repository"]["root"])
    prepare_feedback_store(output)
    previous = _load_record(output)
    python_path, ckb_path = _resolve_runtime(previous, python, ckb)
    protocol = _protocol_text(output, repository, python_path, ckb_path)
    texts = _adapter_texts(protocol)
    roots = _instruction_roots(output)
    internal: dict[str, Any] = {}
    for name, root in roots.items():
        internal[name] = {"root": str(root), "files": _write_exact_root(root, texts)}
    _update_markdown_ownership(output)
    _hide_protocol_files(output)
    workspace_roots = list(previous.get("workspace_roots", [])) if previous else []
    record = {
        "schema_version": AGENT_PROTOCOL_SCHEMA_VERSION,
        "protocol_version": AGENT_PROTOCOL_VERSION,
        "status": "installed",
        "output": str(output),
        "repository": repository,
        "python": str(python_path),
        "ckb": str(ckb_path),
        "internal_roots": internal,
        "workspace_roots": workspace_roots,
        "commands": _command_examples(output, python_path, ckb_path),
        "harness_contract": {
            "codex": "AGENTS.md",
            "opencode": "AGENTS.md",
            "claude-code": "CLAUDE.md imports AGENTS.md",
            "gemini-cli": "GEMINI.md imports AGENTS.md",
            "github-copilot": ".github/copilot-instructions.md",
            "cursor": ".cursor/rules/code-knowledge-builder.mdc",
            "generic": "read AGENTS.md before knowledge-base access",
        },
    }
    json_write(output / "workspace-meta/agent-protocol.json", record)
    return record


def install_agent_protocol(
    output: Path,
    workspace_roots: list[Path],
    *,
    python: Path | None = None,
    ckb: Path | None = None,
) -> dict[str, Any]:
    """Install internal adapters and managed blocks at Harness task roots."""
    output = output.resolve()
    record = project_agent_protocol(output, python=python, ckb=ckb)
    protocol = _protocol_text(output, record["repository"], Path(record["python"]), Path(record["ckb"]))
    texts = _adapter_texts(protocol)
    requested = {Path(str(value["root"])).resolve() for value in record.get("workspace_roots", [])}
    requested.update(root.resolve() for root in workspace_roots)
    merged: dict[str, dict[str, Any]] = {}
    for root in sorted(requested, key=str):
        if not root.is_dir():
            raise CkbError(f"Agent protocol workspace root is missing: {root}")
        if not _workspace_root_allowed(root, output, record["repository"]):
            raise CkbError(f"Agent protocol workspace root must contain the repository or knowledge output: {root}")
        merged[str(root)] = _write_workspace_root(root, texts)
    record["workspace_roots"] = [merged[key] for key in sorted(merged)]
    json_write(output / "workspace-meta/agent-protocol.json", record)
    audit = audit_agent_protocol(output)
    if audit["status"] != "passed":
        raise AuditError(f"Agent protocol audit failed: {output / 'workspace-meta/agent-protocol-audit.json'}")
    return {**record, "audit": audit}


def _expected_internal(output: Path, record: dict[str, Any]) -> tuple[dict[str, str], dict[str, Path]]:
    protocol = _protocol_text(output, str(record["repository"]), Path(record["python"]), Path(record["ckb"]))
    return _adapter_texts(protocol), _instruction_roots(output)


def _audit_note_storage(output: Path) -> list[dict[str, Any]]:
    errors = list(audit_notes(output))
    human = output / "human"
    markdown = output / "markdown"
    meta_root = output / "workspace-meta/notes"
    notes: dict[str, dict[str, Any]] = {}
    for directory in NOTE_DIRECTORIES:
        left = {path.name: path for path in (human / directory).glob("*.md")}
        right = {path.name: path for path in (markdown / directory).glob("*.md")}
        if set(left) != set(right):
            errors.append({"reason": "agent-note-mirror-set-mismatch", "directory": directory, "human_only": sorted(set(left) - set(right)), "markdown_only": sorted(set(right) - set(left))})
        for name in sorted(set(left) & set(right)):
            if left[name].read_bytes() != right[name].read_bytes():
                errors.append({"reason": "agent-note-mirror-byte-mismatch", "path": f"{directory}/{name}"})
                continue
            text = right[name].read_text(encoding="utf-8")
            title = text.splitlines()[0].removeprefix("# ").strip() if text else ""
            relative = f"{directory}/{name}"
            notes[title] = {"relative": relative, "content": text, "kind": next((kind for kind, value in DIRECTORY_BY_KIND.items() if value == directory), "")}
            meta = meta_root / f"{safe_title(title)}.json"
            if not meta.is_file():
                errors.append({"reason": "agent-note-metadata-missing", "path": relative, "title": title})
                continue
            value = json_load(meta)
            if value.get("status") != "agent-reviewed" or value.get("title") != title or value.get("kind") != notes[title]["kind"]:
                errors.append({"reason": "agent-note-metadata-invalid", "path": relative, "metadata": str(meta)})

    index = output / "agent-index.sqlite"
    if index.is_file():
        connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
        try:
            integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
            indexed = {row[0]: {"file": row[1], "content": row[2]} for row in connection.execute("SELECT note_title,note_file,content FROM notes")}
        except sqlite3.DatabaseError as exc:
            errors.append({"reason": "agent-index-read-failed", "detail": str(exc)})
            indexed = {}
            integrity = "error"
        finally:
            connection.close()
        if integrity != "ok":
            errors.append({"reason": "agent-index-integrity", "detail": integrity})
        for title, note in notes.items():
            row = indexed.get(title)
            if row != {"file": note["relative"], "content": note["content"]}:
                errors.append({"reason": "agent-index-note-stale", "title": title, "path": note["relative"]})
        if set(indexed) != set(notes):
            errors.append({"reason": "agent-index-note-set-mismatch", "index_only": sorted(set(indexed) - set(notes)), "file_only": sorted(set(notes) - set(indexed))})
    else:
        errors.append({"reason": "agent-index-missing"})

    machine = output / "machine/knowledge.sqlite"
    if machine.is_file():
        connection = sqlite3.connect(f"file:{machine.as_posix()}?mode=ro", uri=True)
        try:
            integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
            indexed = {
                row[0]: {"file": row[1], "content": row[2], "kind": row[3]}
                for row in connection.execute("SELECT title,human_file,content,kind FROM documents WHERE kind NOT IN ('entity','reference','gap')")
            }
        except sqlite3.DatabaseError as exc:
            errors.append({"reason": "machine-index-read-failed", "detail": str(exc)})
            indexed = {}
            integrity = "error"
        finally:
            connection.close()
        if integrity != "ok":
            errors.append({"reason": "machine-index-integrity", "detail": integrity})
        for title, note in notes.items():
            row = indexed.get(title)
            if row != {"file": note["relative"], "content": note["content"], "kind": note["kind"]}:
                errors.append({"reason": "machine-index-note-stale", "title": title, "path": note["relative"]})
        if set(indexed) != set(notes):
            errors.append({"reason": "machine-index-note-set-mismatch", "index_only": sorted(set(indexed) - set(notes)), "file_only": sorted(set(notes) - set(indexed))})
    else:
        errors.append({"reason": "machine-index-missing"})
    return errors


def audit_agent_protocol(output: Path) -> dict[str, Any]:
    """Verify discovery adapters and every durable Agent-note representation."""
    output = output.resolve()
    record = _load_record(output)
    errors: list[dict[str, Any]] = []
    if not record:
        errors.append({"reason": "agent-protocol-record-missing"})
    elif record.get("protocol_version") != AGENT_PROTOCOL_VERSION:
        errors.append({"reason": "agent-protocol-version-mismatch", "actual": record.get("protocol_version"), "expected": AGENT_PROTOCOL_VERSION})
    if record:
        python = Path(str(record.get("python", "")))
        ckb = Path(str(record.get("ckb", "")))
        if not python.is_file():
            errors.append({"reason": "agent-protocol-python-missing", "path": str(python)})
        if not ckb.is_file():
            errors.append({"reason": "agent-protocol-ckb-missing", "path": str(ckb)})
        texts, roots = _expected_internal(output, record)
        for root_name in INTERNAL_ROOT_NAMES:
            root = roots.get(root_name)
            if root is None:
                errors.append({"reason": "agent-protocol-internal-root-missing", "root": root_name})
                continue
            for key, relative in ADAPTER_PATHS.items():
                path = root / relative
                if not path.is_file():
                    errors.append({"reason": "agent-protocol-adapter-missing", "root": root_name, "path": relative.as_posix()})
                elif path.read_text(encoding="utf-8-sig") != texts[key]:
                    errors.append({"reason": "agent-protocol-adapter-drift", "root": root_name, "path": relative.as_posix()})
        for workspace in record.get("workspace_roots", []):
            root = Path(str(workspace["root"]))
            for key, relative in ADAPTER_PATHS.items():
                path = root / relative
                if not path.is_file():
                    errors.append({"reason": "agent-protocol-workspace-adapter-missing", "root": str(root), "path": relative.as_posix()})
                    continue
                text = path.read_text(encoding="utf-8-sig")
                expected = _managed_block(texts[key])
                if text.count(POLICY_BEGIN) != 1 or text.count(POLICY_END) != 1 or expected not in text:
                    errors.append({"reason": "agent-protocol-workspace-adapter-drift", "root": str(root), "path": relative.as_posix()})
        for root_name in ("markdown", "human"):
            root = roots.get(root_name)
            if root is None:
                continue
            app_path = root / ".obsidian/app.json"
            app = json_load(app_path) if app_path.is_file() else {}
            if any(value not in app.get("userIgnoreFilters", []) for value in OBSIDIAN_IGNORES):
                errors.append({"reason": "agent-protocol-obsidian-ignore-missing", "root": root_name})
            css_path = root / ".obsidian/snippets/ckb.css"
            if not css_path.is_file() or OBSIDIAN_HIDE_CSS not in css_path.read_text(encoding="utf-8"):
                errors.append({"reason": "agent-protocol-obsidian-hide-rule-missing", "root": root_name})
    errors.extend(_audit_note_storage(output))
    work_record_audit = audit_work_record_index(output)
    errors.extend(work_record_audit["errors"])
    feedback_audit = audit_feedback(output)
    errors.extend(feedback_audit["errors"])
    from .output_contract import audit_output_contract

    output_contracts: dict[str, Any] = {}
    for name in ("markdown", "human"):
        vault = output / name
        if vault.is_dir():
            output_contracts[name] = audit_output_contract(output, vault)
            errors.extend(output_contracts[name]["errors"])
    result = {
        "schema_version": AGENT_PROTOCOL_SCHEMA_VERSION,
        "protocol_version": AGENT_PROTOCOL_VERSION,
        "status": "passed" if not errors else "failed",
        "output": str(output),
        "internal_roots": list(INTERNAL_ROOT_NAMES),
        "workspace_root_count": len(record.get("workspace_roots", [])) if record else 0,
        "feedback": feedback_audit,
        "output_contracts": output_contracts,
        "work_record_index": work_record_audit,
        "errors": errors,
    }
    json_write(output / "workspace-meta/agent-protocol-audit.json", result)
    return result


def agent_protocol_status(output: Path) -> dict[str, Any]:
    record = _load_record(output.resolve())
    return {
        "schema_version": AGENT_PROTOCOL_SCHEMA_VERSION,
        "status": "installed" if record else "missing",
        "record": record,
        "audit": audit_agent_protocol(output.resolve()) if record else None,
    }

