def _copilot_hooks(posix: str, powershell: str) -> dict[str, Any]:
    def handler(timeout: int, matcher: str | None = None) -> dict[str, Any]:
        value: dict[str, Any] = {
            "type": "command",
            "bash": posix,
            "powershell": powershell,
            "timeoutSec": timeout,
        }
        if matcher:
            value["matcher"] = matcher
        return value

    # PascalCase selects Copilot's VS Code-compatible snake_case payloads,
    # which keeps the adapter aligned with Codex/Claude without pretending the
    # event names or output decisions are otherwise interchangeable.
    return {
        "version": 1,
        "hooks": {
            "SessionStart": [handler(8)],
            "UserPromptSubmit": [handler(20)],
            "PostToolUse": [handler(8, "Bash|Edit|Write|NotebookEdit")],
            "PostToolUseFailure": [handler(8, "Bash|Edit|Write|NotebookEdit")],
            "Stop": [handler(15)],
            "PreCompact": [handler(8)],
            "SessionEnd": [handler(3)],
        },
    }


def _cursor_hooks(command: str) -> dict[str, Any]:
    def handler(matcher: str | None = None, timeout: int = 8) -> dict[str, Any]:
        value: dict[str, Any] = {"command": command, "timeout": timeout}
        if matcher:
            value["matcher"] = matcher
        return value

    return {
        "version": 1,
        "hooks": {
            "sessionStart": [handler()],
            "beforeSubmitPrompt": [handler("UserPromptSubmit", 20)],
            "postToolUse": [handler("Shell|Write|Delete|MCP:.*")],
            "postToolUseFailure": [handler("Shell|Write|Delete|MCP:.*")],
            "afterFileEdit": [handler("Write")],
            "afterAgentResponse": [handler()],
            "preCompact": [handler()],
            "stop": [handler("Stop", 15)],
            "sessionEnd": [handler(timeout=3)],
        },
    }


def _opencode_stable_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function value(object, keys) {{
  if (!object || typeof object !== "object") return undefined
  for (const key of keys) if (object[key] !== undefined && object[key] !== null) return object[key]
  for (const child of Object.values(object)) {{
    const found = value(child, keys)
    if (found !== undefined) return found
  }}
}}

function text(object) {{
  if (typeof object === "string") return object
  if (Array.isArray(object)) return object.map(text).filter(Boolean).join("\\n")
  if (!object || typeof object !== "object") return ""
  if (typeof object.text === "string") return object.text
  for (const key of ["content", "parts", "message", "delta"]) {{
    const found = text(object[key])
    if (found) return found
  }}
  return ""
}}

function emit(payload) {{
  try {{
    const event = {{ ...payload, harness_pid: process.pid }}
    spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(event), encoding: "utf8", timeout: payload?.ckb_skill_applied ? 20000 : 8000, windowsHide: true }})
  }} catch {{}}
}}

export const CodeKnowledgeBuilderSync = async ({{ directory, worktree }}) => {{
  const cwd = worktree || directory || process.cwd()
  const assistants = new Map()
  return {{
    event: async ({{ event }}) => {{
      const data = event?.properties ?? event?.data ?? event ?? {{}}
      const info = data?.info ?? data
      const sessionID = String(value(info, ["sessionID", "sessionId", "session_id", "id"]) ?? "session-unknown")
      const base = {{ session_id: sessionID, cwd }}
      if (event?.type === "session.created") emit({{ ...base, hook_event_name: "SessionStart", source: "startup", event_id: `session-created:${{sessionID}}` }})
      if (event?.type === "message.updated") {{
        const role = String(value(info, ["role"]) ?? "").toLowerCase()
        const body = text(info)
        const messageID = String(value(info, ["messageID", "messageId", "id"]) ?? "")
        if (role === "user") emit({{ ...base, hook_event_name: "UserPromptSubmit", prompt: body, event_id: `message:${{messageID}}` }})
        if (role === "assistant") {{
          assistants.set(sessionID, body)
          emit({{ ...base, hook_event_name: "AssistantMessage", assistant_message: body, event_id: `message:${{messageID}}` }})
        }}
      }}
      if (event?.type === "command.executed") {{
        const commandName = String(value(data, ["command", "commandName", "name"]) ?? "")
        if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ ...base, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
      }}
      if (event?.type === "file.edited") emit({{ ...base, hook_event_name: "FileChanged", file_path: value(data, ["file", "filePath", "path"]), event: "change" }})
      if (event?.type === "session.compacted") emit({{ ...base, hook_event_name: "PostCompact", trigger: "auto" }})
      if (event?.type === "session.idle") emit({{ ...base, hook_event_name: "Stop", last_assistant_message: assistants.get(sessionID) ?? "", stop_hook_active: false }})
      if (event?.type === "session.deleted") emit({{ ...base, hook_event_name: "SessionEnd", reason: "other" }})
    }},
    "tool.execute.after": async (input, output) => {{
      emit({{
        session_id: String(input?.sessionID ?? input?.sessionId ?? "session-unknown"),
        cwd,
        hook_event_name: "PostToolUse",
        tool_name: String(input?.tool ?? "unknown"),
        tool_use_id: String(input?.callID ?? input?.toolCallID ?? input?.id ?? ""),
        tool_input: input?.args ?? input?.input ?? input,
        tool_response: output,
        status: "completed",
      }})
    }},
  }}
}}
'''


def _opencode_v2_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode-v2", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"
import {{ Plugin }} from "@opencode-ai/plugin"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function emit(payload) {{
  try {{
    const event = {{ ...payload, harness_pid: process.pid }}
    spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(event), encoding: "utf8", timeout: payload?.ckb_skill_applied ? 20000 : 8000, windowsHide: true }})
  }} catch {{}}
}}

function messageText(message) {{
  const parts = message?.parts ?? message?.content ?? []
  if (typeof parts === "string") return parts
  return Array.isArray(parts) ? parts.map((part) => typeof part === "string" ? part : part?.text ?? "").filter(Boolean).join("\\n") : ""
}}

function unwrapMessages(value) {{
  if (Array.isArray(value)) return value
  if (Array.isArray(value?.data)) return value.data
  if (Array.isArray(value?.messages)) return value.messages
  return []
}}

function eventSessionID(event) {{
  return String(event?.sessionID ?? event?.properties?.sessionID ?? event?.data?.sessionID ?? "session-unknown")
}}

function eventCwd(event) {{
  return String(event?.cwd ?? event?.location?.directory ?? event?.properties?.cwd ?? event?.data?.cwd ?? process.cwd())
}}

export default Plugin.define({{
  id: "code-knowledge-builder.sync",
  setup: async (ctx) => {{
    const seenSessions = new Set()
    const sessionCwds = new Map()
    await ctx.session.hook("context", (event) => {{
      const sessionID = String(event.sessionID ?? "session-unknown")
      const cwd = eventCwd(event)
      sessionCwds.set(sessionID, cwd)
      if (!seenSessions.has(sessionID)) {{
        seenSessions.add(sessionID)
        emit({{ session_id: sessionID, cwd, hook_event_name: "SessionStart", source: "startup", event_id: `session:${{sessionID}}` }})
      }}
      const messages = Array.isArray(event.messages) ? event.messages : []
      const latest = [...messages].reverse().find((item) => item?.role === "user")
      if (latest) emit({{ session_id: sessionID, cwd, hook_event_name: "UserPromptSubmit", prompt: messageText(latest), event_id: `message:${{latest.id ?? latest.messageID ?? "latest"}}` }})
    }})
    await ctx.tool.hook("execute.after", (event) => {{
      emit({{
        session_id: String(event.sessionID ?? "session-unknown"),
        cwd: String(event.cwd ?? process.cwd()),
        hook_event_name: "PostToolUse",
        tool_name: String(event.tool ?? "unknown"),
        tool_use_id: String(event.toolCallID ?? event.callID ?? ""),
        tool_input: event.input,
        tool_response: event.status === "error" ? event.error : event.result,
        output_paths: event.outputPaths ?? [],
        status: event.status ?? "completed",
      }})
    }})
    const controller = new AbortController()
    void (async () => {{
      try {{
        for await (const event of ctx.event.subscribe({{ signal: controller.signal }})) {{
          const sessionID = eventSessionID(event)
          const cwd = eventCwd(event)
          if (event.type === "command.executed") {{
            const commandName = String(event?.command ?? event?.properties?.command ?? event?.data?.command ?? "")
            if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ session_id: sessionID, cwd, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
          }}
          if (["session.execution.succeeded", "session.execution.succeeded.1", "session.idle"].includes(event.type)) {{
            const messages = unwrapMessages(await ctx.session.context({{ sessionID }}))
            const latest = [...messages].reverse().find((item) => item?.role === "assistant")
            emit({{ session_id: sessionID, cwd, hook_event_name: "Stop", last_assistant_message: messageText(latest), stop_hook_active: false, event_id: `stop:${{sessionID}}:${{latest?.id ?? event.id ?? event.type}}` }})
          }}
          if (["session.execution.failed", "session.execution.failed.1"].includes(event.type)) emit({{ session_id: sessionID, cwd, hook_event_name: "StopFailure", last_assistant_message: String(event.error?.message ?? event.error ?? "OpenCode 执行失败。"), event_id: `stop-failed:${{sessionID}}:${{event.id ?? event.type}}` }})
          if (event.type === "session.deleted") emit({{ session_id: sessionID, cwd, hook_event_name: "SessionEnd", reason: "other", event_id: `session-end:${{sessionID}}` }})
          if (event.type === "session.compacted") emit({{ session_id: sessionID, cwd, hook_event_name: "PostCompact", trigger: "auto", event_id: `compact:${{sessionID}}:${{event.id ?? "auto"}}` }})
        }}
      }} catch {{}}
    }})()
    return () => {{
      for (const sessionID of seenSessions) emit({{ session_id: sessionID, cwd: sessionCwds.get(sessionID) ?? process.cwd(), hook_event_name: "SessionEnd", reason: "plugin-unload", event_id: `plugin-unload:${{sessionID}}` }})
      controller.abort()
    }}
  }},
}})
'''


def _generic_schema() -> dict[str, Any]:
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "https://code-knowledge-builder.local/automation-event.schema.json",
        "title": "Code Knowledge Builder canonical automation event",
        "type": "object",
        "required": ["canonical_type", "session_id", "cwd"],
        "properties": {
            "canonical_type": {
                "enum": [
                    "skill.applied",
                    "session.start",
                    "turn.prompt",
                    "turn.assistant",
                    "tool.result",
                    "file.changed",
                    "turn.stop",
                    "compact.before",
                    "compact.after",
                    "session.end",
                ]
            },
            "event_id": {"type": "string", "minLength": 1},
            "session_id": {"type": "string", "minLength": 1},
            "turn_id": {"type": "string"},
            "cwd": {"type": "string", "minLength": 1},
            "prompt": {"type": "string"},
            "assistant_message": {"type": "string"},
            "tool_name": {"type": "string"},
            "tool_use_id": {"type": "string"},
            "tool_input": {},
            "tool_output": {},
            "changed_paths": {"type": "array", "items": {"type": "string"}},
            "skill_name": {"type": "string", "const": "code-knowledge-builder"},
            "ckb_skill_applied": {"type": "boolean", "const": True},
            "harness_pid": {"type": "integer", "minimum": 1},
        },
        "additionalProperties": True,
    }


def render_integration(
    harness: str,
    destination: Path,
    python: Path | None = None,
    ckb: Path | None = None,
    registry: Path | None = None,
    *,
    force: bool = False,
) -> dict[str, Any]:
    from .management_agent import binding_schema, harness_capabilities

    if harness not in SUPPORTED_HARNESSES:
        raise CkbError(f"unsupported integration harness: {harness}")
    destination = destination.resolve()
    python = (python or Path(sys.executable)).expanduser().resolve()
    ckb = (ckb or Path(__file__).resolve().parents[1] / "ckb.py").expanduser().resolve()
    registry = (registry or Path.home() / ".ckb" / "automation-registry.json").expanduser().resolve()
    if not python.is_file():
        raise CkbError(f"integration Python executable is missing: {python}")
    if not ckb.is_file():
        raise CkbError(f"integration CKB entrypoint is missing: {ckb}")
    if destination.exists() and any(destination.iterdir()) and not force:
        raise CkbError(f"integration destination is not empty: {destination}; use --force to replace generated files")
    destination.mkdir(parents=True, exist_ok=True)
    posix, windows = _commands(python, ckb, harness, registry)
    windows_args = [str(python), "-X", "utf8", str(ckb), "automation", "hook", "--harness", harness, "--registry", str(registry)]
    powershell = _powershell_command(python, ckb, harness, registry)
    files: list[Path] = []

    def write(relative: str, value: str | dict[str, Any]) -> Path:
        path = destination / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        text = json.dumps(value, ensure_ascii=False, indent=2) + "\n" if isinstance(value, dict) else value
        path.write_text(text, encoding="utf-8", newline="\n")
        files.append(path)
        return path

    if harness == "codex":
        windows, windows_bridge = _codex_windows_bridge(destination, windows_args)
        write(
            ".codex-plugin/plugin.json",
            {
                "name": "code-knowledge-builder-sync",
                "version": INTEGRATION_VERSION,
                "description": "仅在会话明确应用 code-knowledge-builder Skill 后，同步已登记项目的 Codex 会话和修改证据。",
                "author": {"name": "Code Knowledge Builder"},
                "interface": {
                    "displayName": "Code Knowledge Builder Sync",
                    "shortDescription": "同步明确应用 CKB Skill 的项目会话",
                    "longDescription": "会话明确应用 code-knowledge-builder Skill 后，把 Codex 生命周期事件写入脱敏机器队列，并等待 Agent 中文审阅后再进入人类知识库。",
                    "developerName": "Code Knowledge Builder",
                    "category": "Productivity",
                    "capabilities": ["Read", "Write"],
                    "defaultPrompt": "检查当前项目的 Code Knowledge Builder 自动同步状态。",
                },
            },
        )
        write("hooks/ckb-hook.cmd", windows_bridge)
        write("hooks/hooks.json", _codex_hooks(posix, windows))
    elif harness == "claude":
        command = windows if _looks_windows(python) else posix
        write(".claude/settings.json", _claude_hooks(command))
    elif harness == "opencode":
        write(".opencode/plugins/code-knowledge-builder-sync.mjs", _opencode_stable_plugin(python, ckb, registry))
    elif harness == "opencode-v2":
        write(".opencode/plugins/code-knowledge-builder-sync-v2.mjs", _opencode_v2_plugin(python, ckb, registry))
    elif harness == "dsh":
        # The current DSH Codex bridge intentionally reads `command` and ignores
        # Codex's `commandWindows` extension, so stamp the platform command into
        # both fields when rendering on Windows.
        dsh_command = windows if _looks_windows(python) else posix
        write("hooks.json", _codex_hooks(dsh_command, dsh_command, dsh_subset=True))
        config_path = (destination / "hooks.json").as_posix()
        write(
            "cordis.yml.fragment",
            "- dsh-hooks-codex:\n"
            f"    configPath: {json.dumps(config_path)}\n"
            "    model: ckb-sync\n",
        )
    elif harness == "gemini":
        command = windows if _looks_windows(python) else posix
        write(".gemini/settings.json", _gemini_hooks(command))
    elif harness == "copilot":
        write(".github/hooks/code-knowledge-builder.json", _copilot_hooks(posix, powershell))
    elif harness == "cursor":
        command = windows if _looks_windows(python) else posix
        write(".cursor/hooks.json", _cursor_hooks(command))
    else:
        write("automation-event.schema.json", _generic_schema())
        write("management-binding.schema.json", binding_schema())
        write(
            "example-event.json",
            {
                "canonical_type": "skill.applied",
                "event_id": "HARNESS_EVENT_ID",
                "session_id": "HARNESS_SESSION_ID",
                "cwd": "/absolute/project/path",
                "skill_name": "code-knowledge-builder",
                "ckb_skill_applied": True,
            },
        )
        write(
            "example-management-binding.json",
            {
                "schema_version": 1,
                "conversation_id": "HARNESS_CONVERSATION_ID",
                "harness_id": "generic",
                "workspace_root": "/absolute/workspace/path",
                "repo_root": "/absolute/workspace/path/source",
                "knowledge_base": "/absolute/workspace/path/knowledge-base",
                "integration_branch": "INTEGRATION_BRANCH",
                "notification_policy": "none",
            },
        )
    manifest = {
        "schema_version": 1,
        "status": "rendered",
        "integration_version": INTEGRATION_VERSION,
        "harness": harness,
        "python": str(python),
        "ckb": str(ckb),
        "registry": str(registry),
        "project_opt_in_required": True,
        "session_skill_activation_required": True,
        "required_skill": "code-knowledge-builder",
        "transcript_parsing": False,
        "management_capabilities": harness_capabilities(harness),
        "session_stdio_capability": {
            "activation": "exact-skill-application",
            "session_end": harness not in {"dsh"},
            "parent_monitor": (
                "native-plugin-process"
                if harness in {"opencode", "opencode-v2"}
                else "caller-supplied"
                if harness == "generic"
                else "unavailable"
            ),
            "degraded": harness not in {"opencode", "opencode-v2"},
        },
        "files": [str(path.relative_to(destination).as_posix()) for path in files],
    }
    manifest_path = write("integration.json", manifest)
    return {**manifest, "destination": str(destination), "manifest": str(manifest_path)}

from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
import subprocess
import tempfile
import time
import uuid
from pathlib import Path
from typing import Any, Iterable


EXIT_OK = 0
EXIT_INPUT = 2
EXIT_DEPENDENCY = 3
EXIT_REVIEW = 4
EXIT_AUDIT = 5
EXIT_STALE = 6


class CkbError(RuntimeError):
    exit_code = EXIT_INPUT


class DependencyError(CkbError):
    exit_code = EXIT_DEPENDENCY


class ReviewRequired(CkbError):
    exit_code = EXIT_REVIEW


class AuditError(CkbError):
    exit_code = EXIT_AUDIT


class StaleSourceError(CkbError):
    exit_code = EXIT_STALE


def utc_now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def stable_id(prefix: str, *parts: Any) -> str:
    text = "\0".join(str(part) for part in parts)
    value = uuid.uuid5(uuid.NAMESPACE_URL, text).hex
    return f"{prefix}-{value}"


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def json_load(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def json_write(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    os.replace(temporary, path)


def background_process_options(*, visible: bool = False) -> dict[str, Any]:
    """Hide non-interactive Windows child consoles without changing I/O semantics."""
    if visible or os.name != "nt":
        return {}
    creation_flag = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    return {"creationflags": creation_flag} if creation_flag else {}


def run(
    command: list[str],
    *,
    cwd: Path | None = None,
    env: dict[str, str] | None = None,
    check: bool = False,
    timeout: int | None = None,
    visible: bool = False,
) -> subprocess.CompletedProcess[str]:
    completed = subprocess.run(
        command,
        cwd=str(cwd) if cwd else None,
        env=env,
        text=True,
        encoding="utf-8",
        errors="replace",
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=timeout,
        **background_process_options(visible=visible),
    )
    if check and completed.returncode:
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"command failed ({completed.returncode}): {' '.join(command)}\n{detail}")
    return completed


def command_version(executable: str, args: Iterable[str] = ("--version",)) -> dict[str, Any]:
    resolved = shutil.which(executable)
    if not resolved:
        return {"status": "missing", "command": executable, "path": None, "version": None}
    completed = run([resolved, *args], timeout=20)
    text = (completed.stdout or completed.stderr).strip().splitlines()
    return {
        "status": "ready" if completed.returncode == 0 else "broken",
        "command": executable,
        "path": str(Path(resolved).resolve()),
        "version": text[0] if text else None,
        "exit_status": completed.returncode,
    }


def clear_markers(output: Path) -> None:
    for name in (
        ".pending-agent-review",
        ".failed",
        ".complete",
        ".machine.complete",
        ".human.complete",
    ):
        (output / name).unlink(missing_ok=True)


def write_marker(output: Path, name: str, payload: dict[str, Any]) -> None:
    clear_markers(output)
    json_write(output / name, payload)


def safe_title(text: str, limit: int = 120) -> str:
    value = re.sub(r"[\\/:*?\"<>|\[\]]+", "-", text).strip(" .-")
    return (value[:limit] or "untitled").strip()


def path_inside(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
        return True
    except ValueError:
        return False


def safe_rmtree(path: Path, root: Path) -> None:
    """Remove one verified descendant without ever accepting the root itself."""
    resolved_path = path.resolve()
    resolved_root = root.resolve()
    if resolved_path == resolved_root or not path_inside(resolved_path, resolved_root):
        raise CkbError(f"recursive removal target is outside its declared root: {resolved_path}")
    if resolved_path.exists():
        shutil.rmtree(resolved_path)


def temp_directory(prefix: str = "ckb-"):
    return tempfile.TemporaryDirectory(prefix=prefix)

"""Deterministic, location-anchored human feedback for knowledge pages.

The fixed source graph remains generator-owned.  Feedback is stored as machine
JSON under ``workspace-meta`` and projected as small, frontmatter-free Chinese
Markdown records into both human vaults.  Resolved feedback is archived rather
than deleted.
"""

from __future__ import annotations

from collections import defaultdict
import datetime as dt
from pathlib import Path, PurePosixPath
import re
from typing import Any

from .common import CkbError, json_load, json_write, path_inside, safe_title, utc_now


FEEDBACK_SCHEMA_VERSION = 1
FEEDBACK_DIRECTORIES = ("feedback/open", "feedback/resolved")
SEVERITIES = ("error", "warn", "suggest", "info")
SOURCES = ("manual", "obsidian-plugin", "web-viewer")
DECISIONS = ("accepted", "partial", "rejected", "deferred")
SEVERITY_ORDER = {value: index for index, value in enumerate(SEVERITIES)}
STATUS_DIRECTORY = {"open": "open", "resolved": "resolved"}
CHINESE_RE = re.compile(r"[\u3400-\u9fff]")
LONG_HEX = re.compile(r"(?<![0-9A-Fa-f])[0-9A-Fa-f]{40,}(?![0-9A-Fa-f])")


def _contains_chinese(value: Any, minimum_han: int = 2) -> bool:
    return isinstance(value, str) and len(CHINESE_RE.findall(value)) >= minimum_han


def prepare_feedback_store(output: Path) -> dict[str, Any]:
    """Create only the feedback-owned directories for a finalized Markdown KB."""
    output = output.resolve()
    metadata = output / "workspace-meta/feedback"
    for status in STATUS_DIRECTORY.values():
        (metadata / status).mkdir(parents=True, exist_ok=True)
    vaults = []
    for name in ("markdown", "human"):
        root = output / name
        if root.is_dir():
            for relative in FEEDBACK_DIRECTORIES:
                (root / relative).mkdir(parents=True, exist_ok=True)
            vaults.append(str(root.resolve()))
    return {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "ready",
        "metadata_root": str(metadata.resolve()),
        "vaults": vaults,
    }


def _canonical_relative_target(output: Path, target: Path) -> tuple[str, Path, Path]:
    output = output.resolve()
    human = output / "human"
    markdown = output / "markdown"
    if not human.is_dir() or not markdown.is_dir():
        raise CkbError("feedback requires finalized human and markdown knowledge roots")
    raw = str(target).replace("\\", "/")
    candidate = Path(target)
    if candidate.is_absolute():
        resolved = candidate.resolve()
        if path_inside(resolved, human):
            relative = resolved.relative_to(human).as_posix()
        elif path_inside(resolved, markdown):
            relative = resolved.relative_to(markdown).as_posix()
        else:
            raise CkbError("feedback target must be inside OUTPUT/human or OUTPUT/markdown")
    else:
        for prefix in ("human/", "markdown/"):
            if raw.startswith(prefix):
                raw = raw[len(prefix) :]
                break
        pure = PurePosixPath(raw)
        if pure.is_absolute() or ".." in pure.parts:
            raise CkbError("feedback target must be a knowledge-root relative path")
        relative = pure.as_posix().lstrip("./")
    if not relative or relative.startswith("feedback/") or not relative.endswith(".md"):
        raise CkbError("feedback target must be a non-feedback Markdown knowledge page")
    human_target = human / relative
    markdown_target = markdown / relative
    if not human_target.is_file() or not markdown_target.is_file():
        raise CkbError(f"feedback target is missing from the mirrored human knowledge roots: {relative}")
    if human_target.read_bytes() != markdown_target.read_bytes():
        raise CkbError(f"feedback target differs between human and markdown roots: {relative}")
    return relative, human_target, markdown_target


def _read_chinese_body(path: Path, label: str) -> str:
    if not path.is_file():
        raise CkbError(f"{label} body does not exist: {path}")
    value = path.read_text(encoding="utf-8-sig").strip()
    if not value:
        raise CkbError(f"{label} body must not be empty")
    if not _contains_chinese(value):
        raise CkbError(f"{label} narrative must use Simplified Chinese")
    if value.startswith("---\n") or LONG_HEX.search(value):
        raise CkbError(f"{label} body must omit frontmatter and hash-like identifiers")
    return value


def _line_selection(text: str, start_line: int, end_line: int) -> tuple[str, str, str]:
    if start_line < 1 or end_line < start_line:
        raise CkbError("feedback line range must be a positive inclusive range")
    lines = text.splitlines(keepends=True)
    if end_line > len(lines):
        raise CkbError(f"feedback line range exceeds target length: {end_line}>{len(lines)}")
    start_offset = sum(len(value) for value in lines[: start_line - 1])
    end_offset = sum(len(value) for value in lines[:end_line])
    anchor_text = text[start_offset:end_offset]
    if not anchor_text:
        raise CkbError("feedback selection must not be empty")
    return text[max(0, start_offset - 80) : start_offset], anchor_text, text[end_offset : end_offset + 80]


def _next_feedback_id(output: Path) -> str:
    prefix = dt.datetime.now(dt.timezone.utc).strftime("feedback-%Y%m%d-%H%M%S")
    existing = {
        path.stem
        for status in STATUS_DIRECTORY.values()
        for path in (output / "workspace-meta/feedback" / status).glob(f"{prefix}-*.json")
    }
    index = 1
    while f"{prefix}-{index:02d}" in existing:
        index += 1
    return f"{prefix}-{index:02d}"


def _title_of(path: Path) -> str:
    text = path.read_text(encoding="utf-8-sig")
    first = text.splitlines()[0] if text else ""
    return first.removeprefix("# ").strip() or path.stem


def _blockquote(value: str) -> str:
    lines = value.rstrip("\n").splitlines() or [""]
    return "\n".join("> " + line for line in lines)


def _visible_feedback(record: dict[str, Any]) -> str:
    severity_names = {"error": "错误", "warn": "警告", "suggest": "建议", "info": "说明"}
    status_names = {"open": "待处理", "resolved": "已归档"}
    source_names = {"manual": "手动", "obsidian-plugin": "Obsidian", "web-viewer": "本地查看器"}
    decision_names = {"accepted": "采纳", "partial": "部分采纳", "rejected": "不采纳", "deferred": "暂缓"}
    sections = [
        f"# {record['title']}",
        "",
        "标签：#类型/反馈",
        "",
        f"状态：{status_names[record['status']]}",
        f"严重程度：{severity_names[record['severity']]}",
        f"目标：[[{record['target_title']}]]（`{record['target']}` 第 {record['target_lines'][0]}–{record['target_lines'][1]} 行）",
        f"来源：{source_names[record['source']]}，提交者 `{record['author']}`",
        "",
        "## 反馈内容",
        "",
        record["comment"].strip(),
        "",
        "## 锚点摘录",
        "",
        _blockquote(record["anchor_text"]),
    ]
    if record.get("decision"):
        sections.extend(
            [
                "",
                "## 处理结果",
                "",
                f"决议：{decision_names[record['decision']]}。",
                "",
                str(record.get("resolution") or "").strip(),
            ]
        )
        if record.get("applied_record"):
            sections.extend(["", f"落实记录：`{record['applied_record']}`"])
    return "\n".join(sections).rstrip() + "\n"


def _record_path(output: Path, status: str, feedback_id: str) -> Path:
    return output / "workspace-meta/feedback" / STATUS_DIRECTORY[status] / f"{feedback_id}.json"


def _visible_relative(status: str, feedback_id: str) -> Path:
    return Path("feedback") / STATUS_DIRECTORY[status] / f"{feedback_id}.md"


def _write_visible_mirrors(output: Path, record: dict[str, Any]) -> list[str]:
    text = _visible_feedback(record)
    relative = _visible_relative(record["status"], record["id"])
    paths = []
    for root_name in ("markdown", "human"):
        path = output / root_name / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
        paths.append(str(path.resolve()))
    return paths


def create_feedback(
    output: Path,
    target: Path,
    start_line: int,
    end_line: int,
    comment_path: Path,
    severity: str,
    author: str,
    source: str,
) -> dict[str, Any]:
    output = output.resolve()
    if severity not in SEVERITIES:
        raise CkbError(f"feedback severity must be one of: {list(SEVERITIES)}")
    if source not in SOURCES:
        raise CkbError(f"feedback source must be one of: {list(SOURCES)}")
    if not author.strip():
        raise CkbError("feedback author must not be empty")
    prepare_feedback_store(output)
    relative, human_target, _ = _canonical_relative_target(output, target)
    target_text = human_target.read_text(encoding="utf-8-sig")
    before, anchor, after = _line_selection(target_text, start_line, end_line)
    comment = _read_chinese_body(comment_path.resolve(), "feedback")
    feedback_id = _next_feedback_id(output)
    target_title = _title_of(human_target)
    created_at = utc_now()
    record = {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "id": feedback_id,
        "status": "open",
        "target": relative,
        "target_title": target_title,
        "title": f"关于 {target_title} 的反馈（{created_at.replace('T', ' ').removesuffix('Z')} UTC，第 {feedback_id.rsplit('-', 1)[1]} 条）",
        "target_lines": [start_line, end_line],
        "anchor_before": before,
        "anchor_text": anchor,
        "anchor_after": after,
        "severity": severity,
        "author": author.strip(),
        "source": source,
        "created_at_utc": created_at,
        "comment": comment,
        "decision": None,
        "resolution": None,
        "applied_record": None,
        "resolved_at_utc": None,
    }
    json_write(_record_path(output, "open", feedback_id), record)
    record["visible_files"] = _write_visible_mirrors(output, record)
    result = {**record, "anchor": locate_feedback(output, feedback_id)["anchor"]}
    audit = audit_feedback(output)
    if audit["status"] != "passed":
        raise CkbError(f"feedback audit failed after create: {audit['errors'][:10]}")
    return result


def _load_feedback(output: Path, feedback_id: str) -> tuple[dict[str, Any], Path]:
    if not re.fullmatch(r"feedback-\d{8}-\d{6}-\d{2,}", feedback_id):
        raise CkbError("feedback identifier has an invalid shape")
    matches = [path for status in STATUS_DIRECTORY for path in [_record_path(output, status, feedback_id)] if path.is_file()]
    if len(matches) != 1:
        raise CkbError(f"feedback identifier must resolve to exactly one record: {feedback_id}")
    return json_load(matches[0]), matches[0]


def _all_offsets(text: str, needle: str) -> list[int]:
    offsets = []
    start = 0
    while needle:
        value = text.find(needle, start)
        if value < 0:
            break
        offsets.append(value)
        start = value + 1
    return offsets


def _offset_lines(text: str, start: int, end: int) -> list[int]:
    return [text.count("\n", 0, start) + 1, text.count("\n", 0, max(start, end - 1)) + 1]


def _locate_anchor(text: str, record: dict[str, Any]) -> dict[str, Any]:
    start_line, end_line = [int(value) for value in record["target_lines"]]
    lines = text.splitlines(keepends=True)
    if 1 <= start_line <= end_line <= len(lines):
        start = sum(len(value) for value in lines[: start_line - 1])
        end = sum(len(value) for value in lines[:end_line])
        if record["anchor_text"] in text[start:end]:
            return {"status": "line-range", "current_lines": [start_line, end_line], "match_count": 1}
    offsets = _all_offsets(text, str(record["anchor_text"]))
    if len(offsets) == 1:
        start = offsets[0]
        return {
            "status": "unique-text",
            "current_lines": _offset_lines(text, start, start + len(record["anchor_text"])),
            "match_count": 1,
        }
    if len(offsets) > 1:
        window = str(record["anchor_before"]) + str(record["anchor_text"]) + str(record["anchor_after"])
        windows = _all_offsets(text, window)
        if len(windows) == 1:
            start = windows[0] + len(record["anchor_before"])
            return {
                "status": "anchor-window",
                "current_lines": _offset_lines(text, start, start + len(record["anchor_text"])),
                "match_count": len(offsets),
            }
    return {"status": "stale", "current_lines": None, "match_count": len(offsets)}


def locate_feedback(output: Path, feedback_id: str) -> dict[str, Any]:
    output = output.resolve()
    record, path = _load_feedback(output, feedback_id)
    relative, human_target, _ = _canonical_relative_target(output, Path(str(record["target"])))
    anchor = _locate_anchor(human_target.read_text(encoding="utf-8-sig"), record)
    return {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "passed" if anchor["status"] != "stale" else "stale",
        "feedback_id": feedback_id,
        "feedback_status": record["status"],
        "target": relative,
        "record": str(path.resolve()),
        "anchor": anchor,
    }


def _canonical_applied_record(output: Path, path: Path | None) -> str | None:
    if path is None:
        return None
    resolved = path.resolve()
    if not resolved.is_file() or not path_inside(resolved, output.resolve()):
        raise CkbError("applied record must be an existing file inside the knowledge output")
    relative = resolved.relative_to(output.resolve())
    if len(relative.parts) < 3 or relative.parts[0] not in {"human", "markdown"}:
        raise CkbError("applied record must point to a reviewed human knowledge note")
    note_directories = {"analysis", "changes", "pitfalls", "experiments", "sessions"}
    if relative.parts[1] not in note_directories or resolved.suffix.casefold() != ".md":
        raise CkbError("applied record must point to an analysis, change, pitfall, experiment, or session note")
    note_relative = Path(*relative.parts[1:])
    human = output / "human" / note_relative
    markdown = output / "markdown" / note_relative
    if not human.is_file() or not markdown.is_file() or human.read_bytes() != markdown.read_bytes():
        raise CkbError("applied record must have byte-identical human and markdown note mirrors")
    title = _title_of(human)
    metadata = output / "workspace-meta/notes" / f"{safe_title(title)}.json"
    if not metadata.is_file():
        raise CkbError("applied record metadata is missing; create the note through record")
    value = json_load(metadata)
    if value.get("status") != "agent-reviewed" or value.get("title") != title:
        raise CkbError("applied record must have agent-reviewed metadata")
    return relative.as_posix()


def resolve_feedback(
    output: Path,
    feedback_id: str,
    decision: str,
    resolution_path: Path,
    applied_record: Path | None = None,
) -> dict[str, Any]:
    output = output.resolve()
    if decision not in DECISIONS:
        raise CkbError(f"feedback decision must be one of: {list(DECISIONS)}")
    resolution = _read_chinese_body(resolution_path.resolve(), "feedback resolution")
    record, source_path = _load_feedback(output, feedback_id)
    if record.get("status") != "open":
        raise CkbError("only open feedback can receive a new decision")
    applied = _canonical_applied_record(output, applied_record)
    if decision in {"accepted", "partial"} and not applied:
        raise CkbError("accepted or partial feedback requires --applied-record with verified implementation evidence")
    anchor = locate_feedback(output, feedback_id)["anchor"]
    record["decision"] = decision
    record["resolution"] = resolution
    record["applied_record"] = applied
    record["resolution_anchor"] = anchor
    record["resolved_at_utc"] = utc_now() if decision != "deferred" else None
    if decision == "deferred":
        json_write(source_path, record)
        record["visible_files"] = _write_visible_mirrors(output, record)
        audit = audit_feedback(output)
        if audit["status"] != "passed":
            raise CkbError(f"feedback audit failed after defer: {audit['errors'][:10]}")
        return {**record, "anchor": anchor}
    record["status"] = "resolved"
    destination = _record_path(output, "resolved", feedback_id)
    json_write(destination, record)
    source_path.unlink()
    old_relative = _visible_relative("open", feedback_id)
    for root_name in ("markdown", "human"):
        (output / root_name / old_relative).unlink(missing_ok=True)
    record["visible_files"] = _write_visible_mirrors(output, record)
    audit = audit_feedback(output)
    if audit["status"] != "passed":
        raise CkbError(f"feedback audit failed after resolve: {audit['errors'][:10]}")
    return {**record, "anchor": anchor, "record": str(destination.resolve())}


def list_feedback(output: Path, status: str = "open") -> dict[str, Any]:
    output = output.resolve()
    if status not in {"open", "resolved", "all"}:
        raise CkbError("feedback list status must be open, resolved, or all")
    prepare_feedback_store(output)
    statuses = ("open", "resolved") if status == "all" else (status,)
    rows = []
    for value in statuses:
        for path in sorted((output / "workspace-meta/feedback" / value).glob("*.json")):
            record = json_load(path)
            anchor = locate_feedback(output, str(record["id"]))["anchor"]
            rows.append(
                {
                    "id": record["id"],
                    "status": record["status"],
                    "severity": record["severity"],
                    "target": record["target"],
                    "target_title": record["target_title"],
                    "target_lines": record["target_lines"],
                    "comment": record["comment"],
                    "decision": record.get("decision"),
                    "anchor": anchor,
                    "record": str(path.resolve()),
                }
            )
    rows.sort(key=lambda item: (SEVERITY_ORDER.get(item["severity"], 99), item["target"], item["id"]))
    grouped: dict[str, list[str]] = defaultdict(list)
    for row in rows:
        grouped[row["target"]].append(row["id"])
    return {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "ready",
        "selection": status,
        "count": len(rows),
        "grouped_by_target": [{"target": key, "feedback_ids": grouped[key]} for key in sorted(grouped)],
        "feedback": rows,
    }


def audit_feedback(output: Path) -> dict[str, Any]:
    output = output.resolve()
    prepare_feedback_store(output)
    errors: list[dict[str, Any]] = []
    records = []
    seen: set[str] = set()
    seen_titles: set[str] = set()
    for directory_status in ("open", "resolved"):
        root = output / "workspace-meta/feedback" / directory_status
        for path in sorted(root.glob("*.json")):
            try:
                record = json_load(path)
            except Exception as exc:
                errors.append({"reason": "feedback-record-invalid-json", "path": str(path), "detail": str(exc)})
                continue
            feedback_id = str(record.get("id", ""))
            if feedback_id in seen:
                errors.append({"reason": "feedback-id-duplicate", "feedback_id": feedback_id})
            seen.add(feedback_id)
            if path.stem != feedback_id or not re.fullmatch(r"feedback-\d{8}-\d{6}-\d{2,}", feedback_id):
                errors.append({"reason": "feedback-id-invalid", "path": str(path), "feedback_id": feedback_id})
            if record.get("schema_version") != FEEDBACK_SCHEMA_VERSION:
                errors.append({"reason": "feedback-schema-version", "feedback_id": feedback_id})
            required = {
                "id",
                "status",
                "target",
                "target_title",
                "title",
                "target_lines",
                "anchor_before",
                "anchor_text",
                "anchor_after",
                "severity",
                "author",
                "source",
                "created_at_utc",
                "comment",
            }
            missing = sorted(required - set(record))
            line_range = record.get("target_lines")
            if missing or not isinstance(line_range, list) or len(line_range) != 2 or not all(isinstance(value, int) for value in line_range):
                errors.append({"reason": "feedback-record-shape-invalid", "feedback_id": feedback_id, "missing": missing})
                continue
            title = str(record.get("title", ""))
            if title in seen_titles:
                errors.append({"reason": "feedback-visible-title-duplicate", "feedback_id": feedback_id, "title": title})
            seen_titles.add(title)
            if record.get("status") != directory_status:
                errors.append({"reason": "feedback-status-directory-mismatch", "feedback_id": feedback_id})
            if record.get("severity") not in SEVERITIES:
                errors.append({"reason": "feedback-severity-invalid", "feedback_id": feedback_id})
            if record.get("source") not in SOURCES:
                errors.append({"reason": "feedback-source-invalid", "feedback_id": feedback_id})
            if not _contains_chinese(record.get("comment")):
                errors.append({"reason": "feedback-comment-not-chinese", "feedback_id": feedback_id})
            target_valid = True
            try:
                _canonical_relative_target(output, Path(str(record.get("target", ""))))
                location = locate_feedback(output, feedback_id)["anchor"]
            except Exception as exc:
                errors.append({"reason": "feedback-target-invalid", "feedback_id": feedback_id, "detail": str(exc)})
                target_valid = False
                location = {"status": "unavailable"}
            if directory_status == "open" and target_valid and location.get("status") == "stale":
                errors.append({"reason": "feedback-anchor-stale", "feedback_id": feedback_id})
            decision = record.get("decision")
            if directory_status == "open" and decision not in {None, "deferred"}:
                errors.append({"reason": "feedback-open-decision-invalid", "feedback_id": feedback_id})
            if directory_status == "open" and decision == "deferred" and not _contains_chinese(record.get("resolution")):
                errors.append({"reason": "feedback-deferred-resolution-not-chinese", "feedback_id": feedback_id})
            if directory_status == "resolved":
                if decision not in {"accepted", "partial", "rejected"}:
                    errors.append({"reason": "feedback-resolved-decision-invalid", "feedback_id": feedback_id})
                if not _contains_chinese(record.get("resolution")):
                    errors.append({"reason": "feedback-resolution-not-chinese", "feedback_id": feedback_id})
                if decision in {"accepted", "partial"}:
                    applied_value = record.get("applied_record")
                    try:
                        _canonical_applied_record(output, output / str(applied_value)) if applied_value else None
                        applied_valid = bool(applied_value)
                    except CkbError:
                        applied_valid = False
                    if not applied_valid:
                        errors.append({"reason": "feedback-applied-record-missing", "feedback_id": feedback_id})
            relative = _visible_relative(directory_status, feedback_id)
            mirrors = [output / root / relative for root in ("markdown", "human")]
            if not all(path_value.is_file() for path_value in mirrors):
                errors.append({"reason": "feedback-visible-mirror-missing", "feedback_id": feedback_id})
            elif mirrors[0].read_bytes() != mirrors[1].read_bytes():
                errors.append({"reason": "feedback-visible-mirror-differs", "feedback_id": feedback_id})
            else:
                text = mirrors[0].read_text(encoding="utf-8-sig")
                if text.startswith("---\n") or text.count("#类型/反馈") != 1 or LONG_HEX.search(text):
                    errors.append({"reason": "feedback-visible-shape-invalid", "feedback_id": feedback_id})
            records.append({"feedback_id": feedback_id, "status": directory_status, "anchor_status": location.get("status")})
    result = {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "counts": {
            "open": sum(1 for item in records if item["status"] == "open"),
            "resolved": sum(1 for item in records if item["status"] == "resolved"),
            "stale_open": sum(1 for item in records if item["status"] == "open" and item["anchor_status"] == "stale"),
        },
        "records": records,
        "errors": errors,
    }
    json_write(output / "workspace-meta/feedback-audit.json", result)
    return result


def _query_terms(question: str) -> list[str]:
    terms = {value.casefold() for value in re.findall(r"[A-Za-z0-9_.:#/-]{2,}", question)}
    for run in re.findall(r"[\u3400-\u9fff]+", question):
        terms.add(run)
        terms.update(run[index : index + 2] for index in range(max(0, len(run) - 1)))
    return sorted(terms, key=lambda value: (-len(value), value))


def search_feedback(output: Path, question: str, limit: int = 8) -> list[dict[str, Any]]:
    """Return deterministic feedback matches without mutating the knowledge base."""
    output = output.resolve()
    root = output / "workspace-meta/feedback"
    if not root.is_dir():
        return []
    terms = _query_terms(question)
    rows = []
    for status in ("open", "resolved"):
        for path in sorted((root / status).glob("*.json")):
            record = json_load(path)
            haystack = "\n".join(
                str(record.get(field) or "")
                for field in ("target", "target_title", "comment", "resolution", "severity", "decision", "status")
            ).casefold()
            matches = [term for term in terms if term in haystack]
            score = sum(8 + min(len(term), 12) for term in matches)
            if status == "open":
                score += 25
            score += max(0, 8 - 2 * SEVERITY_ORDER.get(str(record.get("severity")), 4))
            if terms and not matches and not re.search(r"反馈|纠错|audit|feedback", question, re.IGNORECASE):
                continue
            rows.append(
                {
                    "feedback_id": record["id"],
                    "title": record["title"],
                    "status": record["status"],
                    "severity": record["severity"],
                    "target": record["target"],
                    "target_title": record["target_title"],
                    "comment": record["comment"],
                    "decision": record.get("decision"),
                    "resolution": record.get("resolution"),
                    "human_file": _visible_relative(status, record["id"]).as_posix(),
                    "score": score,
                }
            )
    rows.sort(key=lambda item: (-item["score"], SEVERITY_ORDER.get(item["severity"], 99), item["target"], item["feedback_id"]))
    return rows[: max(0, limit)]

"""Graphify-compatible graph, community, report, and scoped-query projection.

The source-audited CKB graph remains the sole fact authority. This module adopts
Graphify's staged graph model and invokes its pinned deterministic community
detector after every successful Agent-reviewed merge. It deliberately does not
replace Git blob/range provenance or the CKB completion gates with fuzzy labels.
"""

from __future__ import annotations

from collections import Counter, defaultdict, deque
import hashlib
import json
import math
from pathlib import Path
import re
import sys
from typing import Any, Iterable

from .common import CkbError, json_load, json_write, sha256_file, utc_now


GRAPHIFY_UPSTREAM = "https://github.com/Graphify-Labs/graphify"
GRAPHIFY_COMMIT = "b2cd36267456c166788c95be6e68574064a92a42"
GRAPHIFY_VERSION = "0.9.48"
GRAPHIFY_PIPELINE = ["detect", "extract", "build", "cluster", "report", "export"]
GRAPHIFY_CONFIDENCE = {"EXTRACTED", "INFERRED", "AMBIGUOUS"}
GRAPHIFY_PROJECTION_SCHEMA = 1
REPORT_COMMUNITY_LIMIT = 30
REPORT_MEMBER_LIMIT = 12
QUERY_DEFAULT_BUDGET = 1500
HUMAN_REPORT_KINDS = {"class", "struct", "interface", "record", "function", "method", "constructor", "destructor"}


def _networkx_modules():
    vendor = Path(__file__).resolve().parents[1] / "_vendor"
    if str(vendor) not in sys.path:
        sys.path.insert(0, str(vendor))
    import networkx as nx  # type: ignore
    from _vendor.graphify_vendor.cluster import (  # type: ignore
        cluster,
        label_communities_by_hub,
        score_all,
    )

    return nx, cluster, label_communities_by_hub, score_all


def _canonical_json_sha256(value: Any) -> str:
    raw = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _source_location(entity: dict[str, Any]) -> str:
    source_range = entity.get("range", {})
    start = int(source_range.get("start_line", 0) or 0)
    end = int(source_range.get("end_line", start) or start)
    return f"L{start}" if start == end else f"L{start}-L{end}"


def _node_label(entity: dict[str, Any]) -> str:
    if entity.get("kind") == "file":
        return str(entity.get("path", entity["id"]))
    return str(entity.get("qualified_name") or entity.get("name") or entity["id"])


def _description(entity: dict[str, Any]) -> str:
    return str(
        entity.get("meaning_zh")
        or entity.get("description_zh")
        or entity.get("role_zh")
        or ""
    )


def _confidence(link: dict[str, Any]) -> tuple[str, float, str]:
    """Map CKB provider evidence into Graphify's three deterministic tiers."""
    provider = str(link.get("provider", ""))
    relation = str(link.get("type", "references"))
    lowered = provider.lower()
    if "lexical-candidate" in lowered:
        return "INFERRED", 0.85, "deterministic lexical target resolution"
    if "ambiguous" in lowered or relation in {"possible-reference", "possible-call"}:
        return "AMBIGUOUS", 0.55, "provider marked the target ambiguous"
    return "EXTRACTED", 1.0, "AST/LSP or source-structural evidence"


def _graphify_node(entity: dict[str, Any]) -> dict[str, Any]:
    source_range = entity.get("range", {})
    return {
        "id": entity["id"],
        "label": _node_label(entity),
        "file_type": "code",
        "node_type": entity.get("kind"),
        "language": entity.get("language"),
        "source_file": entity.get("path"),
        "source_location": _source_location(entity),
        "source_range": {
            "start_byte": source_range.get("start_byte"),
            "end_byte": source_range.get("end_byte"),
            "start_line": source_range.get("start_line"),
            "end_line": source_range.get("end_line"),
        },
        "qualified_name": entity.get("qualified_name"),
        "classification": entity.get("classification"),
        "owner_page_id": entity.get("owner_page_id"),
        "description_zh": _description(entity),
        "meaning_zh": entity.get("meaning_zh"),
        "role_zh": entity.get("role_zh"),
        "change_when_zh": entity.get("change_when_zh"),
        "review_status": entity.get("review_status"),
        "commit": entity.get("commit"),
        "blob": entity.get("blob"),
        "chunk_id": entity.get("chunk_id"),
        "scope_classification": entity.get("classification"),
    }


def _graphify_link(link: dict[str, Any], entity_by_id: dict[str, dict[str, Any]]) -> dict[str, Any]:
    confidence, score, reason = _confidence(link)
    source_entity = entity_by_id[link["source"]]
    return {
        "id": link["id"],
        "source": link["source"],
        "target": link["target"],
        "relation": link.get("type", "references"),
        "confidence": confidence,
        "confidence_score": score,
        "confidence_reason": reason,
        "source_file": link.get("evidence", {}).get("source_path") or source_entity.get("path"),
        "provider": link.get("provider"),
        "evidence": link.get("evidence", {}),
        "cross_chunk": bool(link.get("cross_chunk")),
    }


def _build_networkx(nodes: list[dict[str, Any]], links: list[dict[str, Any]]):
    nx, _cluster, _labels, _scores = _networkx_modules()
    graph = nx.MultiDiGraph()
    for node in nodes:
        attrs = {key: value for key, value in node.items() if key != "id"}
        graph.add_node(node["id"], **attrs)
    for link in links:
        attrs = {key: value for key, value in link.items() if key not in {"source", "target"}}
        graph.add_edge(link["source"], link["target"], key=link["id"], **attrs)
    return graph


def _community_records(graph, communities: dict[int, list[str]], labels: dict[int, str], scores: dict[int, float]) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for community_id in sorted(communities):
        members = sorted(communities[community_id])
        hubs = sorted(members, key=lambda value: (-graph.degree(value), value))[:REPORT_MEMBER_LIMIT]
        records.append(
            {
                "id": community_id,
                "label": labels[community_id],
                "members": members,
                "member_count": len(members),
                "cohesion": scores[community_id],
                "hub_ids": hubs,
                "membership_sha256": _canonical_json_sha256(members),
            }
        )
    return records


def _report(
    canonical: dict[str, Any],
    nodes: list[dict[str, Any]],
    links: list[dict[str, Any]],
    communities: list[dict[str, Any]],
    graph,
) -> str:
    by_id = {node["id"]: node for node in nodes}
    readable_nodes = [
        node
        for node in nodes
        if node.get("node_type") in HUMAN_REPORT_KINDS and str(node.get("description_zh") or "").strip()
    ]
    hub_candidates = sorted(
        readable_nodes,
        key=lambda node: (0 if node.get("classification") == "page" else 1, -graph.degree(node["id"]), node["label"], node["id"]),
    )
    hubs: list[dict[str, Any]] = []
    hub_labels: set[str] = set()
    for node in hub_candidates:
        if node["label"] in hub_labels:
            continue
        hub_labels.add(node["label"])
        hubs.append(node)
        if len(hubs) == 12:
            break
    lines = [
        "# 项目关系导览",
        "",
        "> 这份导览把经常一起工作的类和函数聚成职责群，帮助人先理解结构，再进入具体实现。",
        "",
        "## 建议先看的代码",
        "",
    ]
    for node in hubs:
        description = str(node.get("description_zh") or "").strip()
        lines.append(f"- **{node['label']}**：{description}")
    if not hubs:
        lines.append("- 从项目代码导览开始，沿自然双链进入相关职责。")
    lines.extend(["", "## 按职责群浏览", ""])
    for community in communities[:REPORT_COMMUNITY_LIMIT]:
        member_candidates = sorted(
            [value for value in community["members"] if by_id[value].get("node_type") in HUMAN_REPORT_KINDS],
            key=lambda value: (
                0 if by_id[value].get("classification") == "page" else 1,
                0 if str(by_id[value].get("description_zh") or "").strip() else 1,
                -graph.degree(value),
                by_id[value]["label"],
                value,
            ),
        )
        member_ids: list[str] = []
        member_labels: set[str] = set()
        for value in member_candidates:
            if by_id[value]["label"] in member_labels:
                continue
            member_labels.add(by_id[value]["label"])
            member_ids.append(value)
            if len(member_ids) == 8:
                break
        heading = by_id[member_ids[0]]["label"] if member_ids else community["label"]
        lines.append(f"### {heading} 相关职责")
        lines.append("")
        for node_id in member_ids:
            node = by_id[node_id]
            description = str(node.get("description_zh") or "").strip()
            lines.append(f"- **{node['label']}**" + (f"：{description}" if description else ""))
        lines.append("")
    if len(communities) > REPORT_COMMUNITY_LIMIT:
        lines.append("> 为保持阅读节奏，这里只展开最主要的职责群；图查询仍会使用完整关系。")
        lines.append("")
    lines.extend(
        [
            "## 围绕任务继续缩小范围",
            "",
            "```powershell",
            '& PYTHON scripts\\ckb.py query --out OUTPUT "职责关键词" --budget 1500',
            '& PYTHON scripts\\ckb.py path --out OUTPUT "起点类或函数" "目标类或函数"',
            '& PYTHON scripts\\ckb.py explain --out OUTPUT "类名、函数名或职责关键词"',
            "```",
            "",
            "查询会先选择与问题最相关的代码，再沿真实关系扩展到预算允许的范围。",
            "",
        ]
    )
    return "\n".join(lines)


def project_graphify(output: Path, canonical: dict[str, Any]) -> dict[str, Any]:
    """Build the Graphify-compatible projection from the reviewed canonical graph."""
    root = output / "graphify-out"
    root.mkdir(parents=True, exist_ok=True)
    entity_by_id = {entity["id"]: entity for entity in canonical["entities"]}
    nodes = [_graphify_node(entity) for entity in canonical["entities"]]
    links = [_graphify_link(link, entity_by_id) for link in canonical["links"]]
    nodes.sort(key=lambda item: item["id"])
    links.sort(key=lambda item: item["id"])

    graph = _build_networkx(nodes, links)
    _nx, cluster, label_communities_by_hub, score_all = _networkx_modules()
    grouped = cluster(graph)
    labels = label_communities_by_hub(graph, grouped)
    scores = score_all(graph.to_undirected(), grouped)
    communities = _community_records(graph, grouped, labels, scores)
    community_by_node = {
        node_id: community["id"]
        for community in communities
        for node_id in community["members"]
    }
    for node in nodes:
        node["community"] = community_by_node[node["id"]]
        node["community_name"] = labels[community_by_node[node["id"]]]
        node["norm_label"] = node["label"].casefold()

    graph_doc = {
        "directed": True,
        "multigraph": True,
        "graph": {
            "schema": "graphify-node-link",
            "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
            "generator": "code-knowledge-builder",
            "graphify_upstream": GRAPHIFY_UPSTREAM,
            "graphify_commit": GRAPHIFY_COMMIT,
            "graphify_version": GRAPHIFY_VERSION,
            "pipeline": GRAPHIFY_PIPELINE,
            "source_graph": str((output / "graph.json").resolve()),
            "scope": canonical["scope"].get("mode"),
        },
        "nodes": nodes,
        "links": links,
        "hyperedges": [],
        "built_at_commit": canonical["repository"]["commit"],
    }
    graph_path = root / "graph.json"
    communities_path = root / "communities.json"
    report_path = root / "GRAPH_REPORT.md"
    json_write(graph_path, graph_doc)
    json_write(
        communities_path,
        {
            "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
            "graphify_commit": GRAPHIFY_COMMIT,
            "communities": communities,
        },
    )
    report_path.write_text(
        _report(canonical, nodes, links, communities, graph),
        encoding="utf-8",
        newline="\n",
    )
    record = {
        "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
        "status": "projected",
        "root": str(root.resolve()),
        "graph": str(graph_path.resolve()),
        "graph_sha256": sha256_file(graph_path),
        "communities": str(communities_path.resolve()),
        "communities_sha256": sha256_file(communities_path),
        "report": str(report_path.resolve()),
        "report_sha256": sha256_file(report_path),
        "node_count": len(nodes),
        "link_count": len(links),
        "community_count": len(communities),
        "confidence_counts": dict(sorted(Counter(link["confidence"] for link in links).items())),
        "graphify_upstream": GRAPHIFY_UPSTREAM,
        "graphify_commit": GRAPHIFY_COMMIT,
        "graphify_version": GRAPHIFY_VERSION,
        "networkx_version": _nx.__version__,
        "generated_at_utc": utc_now(),
    }
    json_write(root / "projection.json", record)
    return record


def audit_graphify(output: Path, canonical: dict[str, Any], record: dict[str, Any]) -> list[dict[str, Any]]:
    """Validate full-set parity, source provenance, confidence, and communities."""
    errors: list[dict[str, Any]] = []
    root = output / "graphify-out"
    paths = {
        "graph": root / "graph.json",
        "communities": root / "communities.json",
        "report": root / "GRAPH_REPORT.md",
        "projection": root / "projection.json",
    }
    for name, path in paths.items():
        if not path.is_file():
            errors.append({"reason": f"graphify-{name}-missing", "path": str(path)})
    if errors:
        return errors

    projected = json_load(paths["graph"])
    community_doc = json_load(paths["communities"])
    projection_doc = json_load(paths["projection"])
    if projection_doc != record:
        errors.append({"reason": "graphify-projection-record-mismatch"})
    canonical_entities = {entity["id"]: entity for entity in canonical["entities"]}
    projected_nodes = {node["id"]: node for node in projected.get("nodes", [])}
    if set(projected_nodes) != set(canonical_entities):
        errors.append(
            {
                "reason": "graphify-node-set-mismatch",
                "missing": sorted(set(canonical_entities) - set(projected_nodes)),
                "extra": sorted(set(projected_nodes) - set(canonical_entities)),
            }
        )
    for entity_id in sorted(set(canonical_entities) & set(projected_nodes)):
        entity = canonical_entities[entity_id]
        node = projected_nodes[entity_id]
        source_range = entity.get("range", {})
        expected = {
            "source_file": entity.get("path"),
            "source_location": _source_location(entity),
            "commit": entity.get("commit"),
            "blob": entity.get("blob"),
            "classification": entity.get("classification"),
            "owner_page_id": entity.get("owner_page_id"),
            "source_range": {
                "start_byte": source_range.get("start_byte"),
                "end_byte": source_range.get("end_byte"),
                "start_line": source_range.get("start_line"),
                "end_line": source_range.get("end_line"),
            },
        }
        if any(node.get(key) != value for key, value in expected.items()):
            errors.append({"reason": "graphify-node-provenance-mismatch", "id": entity_id})

    canonical_links = {link["id"]: link for link in canonical["links"]}
    projected_links = {link["id"]: link for link in projected.get("links", [])}
    if set(projected_links) != set(canonical_links):
        errors.append(
            {
                "reason": "graphify-link-set-mismatch",
                "missing": sorted(set(canonical_links) - set(projected_links)),
                "extra": sorted(set(projected_links) - set(canonical_links)),
            }
        )
    for link_id in sorted(set(canonical_links) & set(projected_links)):
        source = canonical_links[link_id]
        link = projected_links[link_id]
        if link.get("source") != source["source"] or link.get("target") != source["target"] or link.get("relation") != source.get("type"):
            errors.append({"reason": "graphify-link-fact-mismatch", "id": link_id})
        if link.get("confidence") not in GRAPHIFY_CONFIDENCE:
            errors.append({"reason": "graphify-confidence-invalid", "id": link_id})
        if not link.get("provider") or not link.get("source_file"):
            errors.append({"reason": "graphify-link-evidence-missing", "id": link_id})
        if link.get("source") not in projected_nodes or link.get("target") not in projected_nodes:
            errors.append({"reason": "graphify-link-dangling", "id": link_id})

    memberships = [
        node_id
        for community in community_doc.get("communities", [])
        for node_id in community.get("members", [])
    ]
    if len(memberships) != len(set(memberships)) or set(memberships) != set(projected_nodes):
        errors.append({"reason": "graphify-community-cover-mismatch"})
    for community in community_doc.get("communities", []):
        if community.get("membership_sha256") != _canonical_json_sha256(sorted(community.get("members", []))):
            errors.append({"reason": "graphify-community-signature-mismatch", "id": community.get("id")})
    if record.get("community_count") != len(community_doc.get("communities", [])):
        errors.append({"reason": "graphify-community-count-contract-mismatch"})

    if projected.get("built_at_commit") != canonical["repository"]["commit"]:
        errors.append({"reason": "graphify-commit-mismatch"})
    graph_meta = projected.get("graph", {})
    if graph_meta.get("graphify_commit") != GRAPHIFY_COMMIT or graph_meta.get("pipeline") != GRAPHIFY_PIPELINE:
        errors.append({"reason": "graphify-upstream-provenance-mismatch"})
    if record.get("graphify_commit") != GRAPHIFY_COMMIT or record.get("graphify_version") != GRAPHIFY_VERSION:
        errors.append({"reason": "graphify-projection-upstream-mismatch"})
    hash_expectations = {
        "graph_sha256": paths["graph"],
        "communities_sha256": paths["communities"],
        "report_sha256": paths["report"],
    }
    for field, path in hash_expectations.items():
        if record.get(field) != sha256_file(path):
            errors.append({"reason": f"graphify-{field}-mismatch"})
    if record.get("node_count") != len(projected_nodes) or record.get("link_count") != len(projected_links):
        errors.append({"reason": "graphify-count-contract-mismatch"})
    report = paths["report"].read_text(encoding="utf-8")
    if GRAPHIFY_COMMIT in report or canonical["repository"]["commit"] in report:
        errors.append({"reason": "graphify-report-exposes-machine-commit"})
    required_headings = ("# 项目关系导览", "## 建议先看的代码", "## 按职责群浏览", "## 围绕任务继续缩小范围")
    if any(heading not in report for heading in required_headings):
        errors.append({"reason": "graphify-human-report-incomplete"})
    if any(marker in report for marker in ("degree `", "cohesion=", "分类 `", "EXTRACTED：", "INFERRED：", "AMBIGUOUS：")):
        errors.append({"reason": "graphify-report-exposes-machine-properties"})
    return errors


def _load_projected_graph(output: Path) -> tuple[dict[str, Any], dict[str, dict[str, Any]], list[dict[str, Any]]]:
    path = output / "graphify-out" / "graph.json"
    if not path.is_file():
        raise CkbError(f"finalize must create Graphify projection first: {path}")
    graph = json_load(path)
    nodes = {node["id"]: node for node in graph.get("nodes", [])}
    links = graph.get("links", [])
    if not nodes:
        raise CkbError(f"Graphify projection has no nodes: {path}")
    return graph, nodes, links


def _terms(text: str) -> list[str]:
    terms = {
        token.casefold()
        for token in re.findall(r"[\w.$:/\\-]+", text, flags=re.UNICODE)
        if len(token) >= 2
    }
    # Standard-library deterministic CJK segmentation: retain each complete run
    # and add adjacent bigrams, so "订单库存处理" can match separate "订单" and
    # "库存" evidence without jieba, an LLM, or host-specific tokenization.
    for run in re.findall(r"[\u3400-\u9fff]+", text):
        terms.update(run[index : index + 2] for index in range(max(0, len(run) - 1)))
    return sorted(terms, key=lambda value: (-len(value), value))


def _seed_scores(question: str, nodes: dict[str, dict[str, Any]]) -> list[tuple[int, str]]:
    terms = _terms(question)
    lowered_question = question.casefold()
    scored: list[tuple[int, str]] = []
    for node_id, node in nodes.items():
        label = str(node.get("label", "")).casefold()
        qname = str(node.get("qualified_name", "")).casefold()
        path = str(node.get("source_file", "")).casefold()
        description = str(node.get("description_zh", "")).casefold()
        haystacks = (label, qname, path, description)
        score = 0
        if lowered_question in haystacks or any(value and value in lowered_question for value in (label, qname)):
            score += 100
        for term in terms:
            if term == label or term == qname:
                score += 30
            elif term in label or term in qname:
                score += 12
            elif term in path:
                score += 6
            elif term in description:
                score += 3
        if score:
            scored.append((score, node_id))
    return sorted(scored, key=lambda value: (-value[0], value[1]))


def _adjacency(nodes: dict[str, dict[str, Any]], links: list[dict[str, Any]]) -> dict[str, list[tuple[str, dict[str, Any]]]]:
    result: dict[str, list[tuple[str, dict[str, Any]]]] = defaultdict(list)
    for link in links:
        if link["source"] in nodes and link["target"] in nodes:
            result[link["source"]].append((link["target"], link))
            result[link["target"]].append((link["source"], link))
    for node_id in result:
        result[node_id].sort(key=lambda row: (row[0], row[1]["id"]))
    return result


def _query_size(nodes: Iterable[dict[str, Any]], links: Iterable[dict[str, Any]]) -> int:
    payload = {"nodes": list(nodes), "links": list(links)}
    return math.ceil(len(json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")) / 3)


def query_graph(output: Path, question: str, budget: int = QUERY_DEFAULT_BUDGET, dfs: bool = False) -> dict[str, Any]:
    if budget <= 0:
        raise CkbError("query budget must be positive")
    _graph, nodes, links = _load_projected_graph(output)
    scored = _seed_scores(question, nodes)
    if not scored:
        raise CkbError(f"no Graphify node matched query: {question}")
    seeds = [node_id for _score, node_id in scored[:5]]
    adjacency = _adjacency(nodes, links)
    primary_seed = next((seed for seed in seeds if adjacency.get(seed)), seeds[0])
    # Traverse from one structurally connected seed. Enqueuing all fuzzy seeds
    # first spends a small budget on disconnected labels before BFS can include
    # the relations that explain why the first match matters.
    frontier: deque[tuple[str, int]] = deque([(primary_seed, 0)])
    selected: list[str] = []
    selected_set: set[str] = set()
    max_depth = 4
    while frontier:
        node_id, depth = frontier.pop() if dfs else frontier.popleft()
        if node_id in selected_set:
            continue
        candidate_ids = selected + [node_id]
        candidate_set = set(candidate_ids)
        candidate_links = [link for link in links if link["source"] in candidate_set and link["target"] in candidate_set]
        if selected and _query_size((nodes[value] for value in candidate_ids), candidate_links) > budget:
            continue
        selected.append(node_id)
        selected_set.add(node_id)
        if depth >= max_depth:
            continue
        neighbors = adjacency.get(node_id, [])
        ordered = reversed(neighbors) if dfs else neighbors
        for neighbor, _link in ordered:
            if neighbor not in selected_set:
                frontier.append((neighbor, depth + 1))
    selected_links = [link for link in links if link["source"] in selected_set and link["target"] in selected_set]
    selected_nodes = [nodes[node_id] for node_id in selected]
    files = sorted({node.get("source_file") for node in selected_nodes if node.get("source_file")})
    result = {
        "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
        "status": "passed",
        "question": question,
        "traversal": "dfs" if dfs else "bfs",
        "budget": budget,
        "estimated_tokens": _query_size(selected_nodes, selected_links),
        "seed_ids": seeds,
        "primary_seed_id": primary_seed,
        "nodes": selected_nodes,
        "links": selected_links,
        "source_files": files,
        "graphify_commit": GRAPHIFY_COMMIT,
    }
    query_dir = output / "graphify-out" / "queries"
    query_dir.mkdir(parents=True, exist_ok=True)
    query_id = hashlib.sha256(f"{question}\0{budget}\0{dfs}".encode("utf-8")).hexdigest()[:16]
    json_write(query_dir / f"query-{query_id}.json", result)
    result["record"] = str((query_dir / f"query-{query_id}.json").resolve())
    return result


def _resolve_node(term: str, nodes: dict[str, dict[str, Any]]) -> str:
    if term in nodes:
        return term
    folded = term.casefold()
    exact = sorted(
        node_id
        for node_id, node in nodes.items()
        if folded in {str(node.get("label", "")).casefold(), str(node.get("qualified_name", "")).casefold()}
    )
    if len(exact) == 1:
        return exact[0]
    exact_pages = [node_id for node_id in exact if nodes[node_id].get("classification") == "page"]
    if len(exact_pages) == 1:
        return exact_pages[0]
    partial = sorted(
        node_id
        for node_id, node in nodes.items()
        if folded in str(node.get("label", "")).casefold()
        or folded in str(node.get("qualified_name", "")).casefold()
        or folded in str(node.get("source_file", "")).casefold()
    )
    candidates = exact or partial
    candidate_pages = [node_id for node_id in candidates if nodes[node_id].get("classification") == "page"]
    if len(candidate_pages) == 1:
        return candidate_pages[0]
    if len(candidates) != 1:
        raise CkbError(f"node selector must match exactly one node: {term}; candidates={candidates[:20]}")
    return candidates[0]


def shortest_path(output: Path, source: str, target: str) -> dict[str, Any]:
    _graph, nodes, links = _load_projected_graph(output)
    source_id = _resolve_node(source, nodes)
    target_id = _resolve_node(target, nodes)
    adjacency = _adjacency(nodes, links)
    queue: deque[str] = deque([source_id])
    previous: dict[str, tuple[str, str] | None] = {source_id: None}
    while queue and target_id not in previous:
        current = queue.popleft()
        for neighbor, link in adjacency.get(current, []):
            if neighbor not in previous:
                previous[neighbor] = (current, link["id"])
                queue.append(neighbor)
    if target_id not in previous:
        raise CkbError(f"no graph path between {source} and {target}")
    node_ids: list[str] = []
    link_ids: list[str] = []
    cursor = target_id
    while True:
        node_ids.append(cursor)
        step = previous[cursor]
        if step is None:
            break
        cursor, link_id = step
        link_ids.append(link_id)
    node_ids.reverse()
    link_ids.reverse()
    link_by_id = {link["id"]: link for link in links}
    return {
        "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
        "status": "passed",
        "source": source_id,
        "target": target_id,
        "node_ids": node_ids,
        "nodes": [nodes[node_id] for node_id in node_ids],
        "links": [link_by_id[link_id] for link_id in link_ids],
        "hop_count": len(link_ids),
        "graphify_commit": GRAPHIFY_COMMIT,
    }


def explain_node(output: Path, selector: str) -> dict[str, Any]:
    _graph, nodes, links = _load_projected_graph(output)
    node_id = _resolve_node(selector, nodes)
    related = [link for link in links if link["source"] == node_id or link["target"] == node_id]
    related.sort(key=lambda item: (item["relation"], item["id"]))
    neighbor_ids = sorted(
        {
            link["target"] if link["source"] == node_id else link["source"]
            for link in related
        }
    )
    return {
        "schema_version": GRAPHIFY_PROJECTION_SCHEMA,
        "status": "passed",
        "node": nodes[node_id],
        "neighbors": [nodes[value] for value in neighbor_ids],
        "links": related,
        "graphify_commit": GRAPHIFY_COMMIT,
    }

"""Explicit, bounded contracts for the optional LLM keyword fallback."""

from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import time
from typing import Any, Sequence

from .common import CkbError, background_process_options, json_load, json_write


KEYWORD_FALLBACK_SCHEMA_VERSION = 1
KEYWORD_PROMPT_SCHEMA = "ckb-keyword-fallback-v1"
MAX_KEYWORDS = 16
MAX_ANCHORS = 12
MAX_REWRITES = 4
MAX_KEYWORD_CHARS = 80
MAX_ANCHOR_CHARS = 160
MAX_REWRITE_CHARS = 320

_MACHINE_TOKEN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:/-]{0,127}$")
_KEYWORD_TEXT = re.compile(r"^[\w\u3400-\u9fff./:+# -]+$", flags=re.UNICODE)
_ANCHOR_TEXT = re.compile(
    r"^[A-Za-z_][A-Za-z0-9_]*(?:(?:::|\.)[A-Za-z_][A-Za-z0-9_]*)*$"
)
_REWRITE_TEXT = re.compile(r"^[\w\u3400-\u9fff\s./:+#(),（）-]+$", flags=re.UNICODE)
_PROMPT_INJECTION = re.compile(
    r"(?:"
    r"(?:ignore|disregard).{0,24}(?:previous|system|instruction)|"
    r"system\s*(?:prompt|message)|developer\s*message|jailbreak|"
    r"<\s*/?(?:script|system)|"
    r"忽略.{0,12}(?:之前|以上|系统|指令)|系统提示|开发者消息|越狱"
    r")",
    flags=re.IGNORECASE,
)
_CREDENTIAL_SHAPE = re.compile(
    r"(?:sk-[A-Za-z0-9_-]{20,}|bearer\s+[A-Za-z0-9._-]{20,})",
    flags=re.IGNORECASE,
)
_FAILURE_TYPES = {
    "invalid-json",
    "invalid-output",
    "missing-credentials",
    "process-failed",
    "rate-limit",
    "timeout",
    "unavailable",
}
_CACHE_FIELDS = {
    "schema_version",
    "status",
    "cache_key",
    "input_hash",
    "prompt_schema",
    "provider",
    "model",
    "version",
    "response",
}
_REQUEST_FIELDS = {
    "schema_version",
    "status",
    "input_hash",
    "prompt_schema",
    "trigger",
    "original",
    "provider",
    "model_candidates",
    "validated_extensions",
    "final",
}


@dataclass(frozen=True)
class KeywordProviderConfig:
    """Public identity and bounded execution settings for one provider adapter."""

    command: tuple[str, ...]
    provider: str
    model: str
    version: str
    timeout_seconds: float = 20.0
    retries: int = 1
    required_environment: tuple[str, ...] = ()


@dataclass(frozen=True)
class KeywordFallbackOptions:
    """One explicit retrieval request's trigger and provider settings."""

    config: KeywordProviderConfig
    force: bool = False
    use_cache: bool = True


def keyword_input_hash(question: str) -> str:
    return hashlib.sha256(question.encode("utf-8")).hexdigest()


def keyword_request_id(question: str) -> str:
    return f"keyword-{keyword_input_hash(question)[:24]}"


def keyword_cache_key(question: str, config: KeywordProviderConfig) -> str:
    validate_provider_config(config)
    material = {
        "input_hash": keyword_input_hash(question),
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
    }
    serialized = json.dumps(material, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(serialized.encode("ascii")).hexdigest()


def canonical_keyword_request(question: str) -> dict[str, Any]:
    """Build the only request shape accepted by command/stdio providers."""

    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
        "request_id": keyword_request_id(question),
        "input_hash": keyword_input_hash(question),
        "question": question,
        "limits": {
            "keywords": MAX_KEYWORDS,
            "anchors": MAX_ANCHORS,
            "rewrites": MAX_REWRITES,
            "keyword_chars": MAX_KEYWORD_CHARS,
            "anchor_chars": MAX_ANCHOR_CHARS,
            "rewrite_chars": MAX_REWRITE_CHARS,
        },
    }


def _machine_token(value: Any, name: str) -> str:
    if not isinstance(value, str) or not _MACHINE_TOKEN.fullmatch(value):
        raise CkbError(f"keyword provider {name} must be a bounded machine token")
    return value


def validate_provider_config(config: KeywordProviderConfig) -> None:
    if not config.command or any(not isinstance(value, str) or not value for value in config.command):
        raise CkbError("keyword provider command must contain at least one non-empty argument")
    _machine_token(config.provider, "provider")
    _machine_token(config.model, "model")
    _machine_token(config.version, "version")
    if not 0.1 <= config.timeout_seconds <= 300.0:
        raise CkbError("keyword provider timeout must be between 0.1 and 300 seconds")
    if config.retries not in {0, 1}:
        raise CkbError("keyword provider retries must be zero or one")
    for name in config.required_environment:
        if not isinstance(name, str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,127}", name):
            raise CkbError("keyword provider required environment names must be bounded identifiers")


def _bounded_strings(
    value: Any,
    *,
    name: str,
    maximum_items: int,
    maximum_chars: int,
    pattern: re.Pattern[str],
) -> list[str]:
    if not isinstance(value, list) or len(value) > maximum_items:
        raise CkbError(f"keyword provider {name} must be an array with at most {maximum_items} items")
    result: list[str] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, str):
            raise CkbError(f"keyword provider {name} items must be strings")
        normalized = item.strip()
        if not normalized or len(normalized) > maximum_chars:
            raise CkbError(f"keyword provider {name} items must contain 1 to {maximum_chars} characters")
        if not pattern.fullmatch(normalized):
            raise CkbError(f"keyword provider {name} contains unsupported characters")
        if _PROMPT_INJECTION.search(normalized):
            raise CkbError(f"keyword provider {name} contains prompt-injection text")
        if _CREDENTIAL_SHAPE.search(normalized):
            raise CkbError(f"keyword provider {name} contains credential-shaped text")
        identity = normalized.casefold()
        if identity in seen:
            raise CkbError(f"keyword provider {name} contains duplicate items")
        seen.add(identity)
        result.append(normalized)
    return result


def _usage(value: Any) -> dict[str, Any]:
    if value is None:
        value = {}
    if not isinstance(value, dict):
        raise CkbError("keyword provider usage must be an object")
    allowed = {"input_tokens", "output_tokens", "total_tokens", "cost_usd"}
    if set(value) - allowed:
        raise CkbError("keyword provider usage contains unsupported fields")
    result: dict[str, Any] = {}
    for name in ("input_tokens", "output_tokens", "total_tokens"):
        item = value.get(name, 0)
        if isinstance(item, bool) or not isinstance(item, int) or item < 0:
            raise CkbError(f"keyword provider usage {name} must be a non-negative integer")
        result[name] = item
    cost = value.get("cost_usd", 0.0)
    if isinstance(cost, bool) or not isinstance(cost, (int, float)) or cost < 0:
        raise CkbError("keyword provider usage cost_usd must be a non-negative number")
    result["cost_usd"] = round(float(cost), 8)
    if result["total_tokens"] and result["total_tokens"] != result["input_tokens"] + result["output_tokens"]:
        raise CkbError("keyword provider usage total_tokens does not match input plus output")
    return result


def validate_provider_response(
    value: Any,
    *,
    question: str,
    config: KeywordProviderConfig,
) -> dict[str, Any]:
    """Validate and normalize model output before it reaches deterministic retrieval."""

    validate_provider_config(config)
    if not isinstance(value, dict):
        raise CkbError("keyword provider response must be a JSON object")
    allowed = {
        "schema_version",
        "status",
        "failure_type",
        "request_id",
        "provider",
        "model",
        "version",
        "keywords",
        "anchors",
        "rewrites",
        "usage",
    }
    if set(value) - allowed:
        raise CkbError("keyword provider response contains unsupported fields")
    if value.get("schema_version") != KEYWORD_FALLBACK_SCHEMA_VERSION:
        raise CkbError("keyword provider schema version mismatch")
    status = value.get("status")
    if status != "passed":
        failure_type = value.get("failure_type")
        if status != "failed" or failure_type not in _FAILURE_TYPES:
            raise CkbError("keyword provider failure response is not canonical")
        return {
            "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
            "status": "failed",
            "failure_type": failure_type,
            "request_id": keyword_request_id(question),
            "provider": config.provider,
            "model": config.model,
            "version": config.version,
            "keywords": [],
            "anchors": [],
            "rewrites": [],
            "usage": _usage(value.get("usage")),
        }
    identity = {
        "request_id": keyword_request_id(question),
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
    }
    for name, expected in identity.items():
        if value.get(name) != expected:
            raise CkbError(f"keyword provider {name} does not match the request configuration")
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed",
        **identity,
        "keywords": _bounded_strings(
            value.get("keywords"),
            name="keywords",
            maximum_items=MAX_KEYWORDS,
            maximum_chars=MAX_KEYWORD_CHARS,
            pattern=_KEYWORD_TEXT,
        ),
        "anchors": _bounded_strings(
            value.get("anchors"),
            name="anchors",
            maximum_items=MAX_ANCHORS,
            maximum_chars=MAX_ANCHOR_CHARS,
            pattern=_ANCHOR_TEXT,
        ),
        "rewrites": _bounded_strings(
            value.get("rewrites"),
            name="rewrites",
            maximum_items=MAX_REWRITES,
            maximum_chars=MAX_REWRITE_CHARS,
            pattern=_REWRITE_TEXT,
        ),
        "usage": _usage(value.get("usage")),
    }


def parse_provider_json(raw: str) -> Any:
    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise CkbError("keyword provider returned invalid JSON") from exc


def _failure(question: str, config: KeywordProviderConfig, failure_type: str) -> dict[str, Any]:
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "failed",
        "failure_type": failure_type,
        "request_id": keyword_request_id(question),
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
        "keywords": [],
        "anchors": [],
        "rewrites": [],
        "usage": _usage({}),
    }


def keyword_cache_path(output: Path, question: str, config: KeywordProviderConfig) -> Path:
    return _cache_path(output, keyword_cache_key(question, config))


def _cache_path(output: Path, cache_key: str) -> Path:
    return output.resolve() / "workspace-meta" / "keyword-fallback" / "cache" / f"{cache_key}.json"


def _cache_record(question: str, config: KeywordProviderConfig, response: dict[str, Any]) -> dict[str, Any]:
    cache_key = keyword_cache_key(question, config)
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed",
        "cache_key": cache_key,
        "input_hash": keyword_input_hash(question),
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
        "response": response,
    }


def _read_cache(output: Path, question: str, config: KeywordProviderConfig) -> dict[str, Any] | None:
    path = _cache_path(output, keyword_cache_key(question, config))
    if not path.is_file():
        return None
    try:
        record = json_load(path)
        expected = _cache_record(question, config, record.get("response") if isinstance(record, dict) else {})
        if not isinstance(record, dict) or set(record) != _CACHE_FIELDS:
            return None
        for name in _CACHE_FIELDS - {"response"}:
            if record.get(name) != expected.get(name):
                return None
        response = validate_provider_response(record.get("response"), question=question, config=config)
        if response.get("status") != "passed":
            return None
        return response
    except (CkbError, OSError, ValueError, TypeError):
        return None


def _write_cache(output: Path, question: str, config: KeywordProviderConfig, response: dict[str, Any]) -> Path:
    record = _cache_record(question, config, response)
    path = _cache_path(output, record["cache_key"])
    json_write(path, record)
    return path


def _transient(failure_type: str) -> bool:
    return failure_type in {"process-failed", "rate-limit", "timeout", "unavailable"}


def run_keyword_provider(
    output: Path,
    question: str,
    config: KeywordProviderConfig,
    *,
    use_cache: bool = True,
) -> dict[str, Any]:
    """Call one explicit command/stdio adapter and return only validated fields."""

    validate_provider_config(config)
    missing = sorted(name for name in config.required_environment if not os.environ.get(name))
    if missing:
        return {
            **_failure(question, config, "missing-credentials"),
            "attempts": 0,
            "latency_ms": 0.0,
            "cache_hit": False,
            "missing_environment": missing,
        }
    if use_cache:
        cached = _read_cache(output, question, config)
        if cached is not None:
            return {
                **cached,
                "cached_usage": cached.get("usage", _usage({})),
                "usage": _usage({}),
                "attempts": 0,
                "latency_ms": 0.0,
                "cache_hit": True,
                "cache_key": keyword_cache_key(question, config),
            }
    request = json.dumps(canonical_keyword_request(question), ensure_ascii=False, separators=(",", ":"))
    started = time.perf_counter_ns()
    attempts = 0
    response: dict[str, Any] = _failure(question, config, "unavailable")
    for attempt in range(config.retries + 1):
        attempts = attempt + 1
        failure_type: str | None = None
        try:
            completed = subprocess.run(
                list(config.command),
                input=request,
                text=True,
                encoding="utf-8",
                errors="replace",
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=config.timeout_seconds,
                check=False,
                **background_process_options(),
            )
            if completed.returncode:
                diagnostic = f"{completed.stdout}\n{completed.stderr}"
                failure_type = "rate-limit" if re.search(r"rate[ _-]*limit|too many requests|\b429\b", diagnostic, re.IGNORECASE) else "process-failed"
                response = _failure(question, config, failure_type)
            else:
                try:
                    parsed = parse_provider_json(completed.stdout)
                    response = validate_provider_response(parsed, question=question, config=config)
                    failure_type = response.get("failure_type") if response.get("status") != "passed" else None
                except CkbError as exc:
                    failure_type = "invalid-json" if "invalid JSON" in str(exc) else "invalid-output"
                    response = _failure(question, config, failure_type)
        except subprocess.TimeoutExpired:
            failure_type = "timeout"
            response = _failure(question, config, failure_type)
        except (FileNotFoundError, OSError):
            failure_type = "unavailable"
            response = _failure(question, config, failure_type)
        if response.get("status") == "passed" or not failure_type or not _transient(failure_type):
            break
    latency_ms = round((time.perf_counter_ns() - started) / 1_000_000, 6)
    result = {
        **response,
        "attempts": attempts,
        "latency_ms": latency_ms,
        "cache_hit": False,
        "cache_key": keyword_cache_key(question, config),
    }
    if response.get("status") == "passed" and use_cache:
        result["cache"] = str(_write_cache(output, question, config, response).resolve())
    return result


def audit_keyword_cache(output: Path) -> dict[str, Any]:
    """Check bounded cache records without reading or requiring provider secrets."""

    root = output.resolve() / "workspace-meta" / "keyword-fallback" / "cache"
    if not root.is_dir():
        return {"schema_version": 1, "status": "passed", "records": 0, "errors": []}
    errors: list[str] = []
    records = 0
    for path in sorted(root.glob("*.json")):
        records += 1
        try:
            value = json_load(path)
        except (OSError, ValueError) as exc:
            errors.append(f"{path.name}: invalid cache JSON: {type(exc).__name__}")
            continue
        if not isinstance(value, dict) or set(value) != _CACHE_FIELDS:
            errors.append(f"{path.name}: fields differ from the fixed cache schema")
            continue
        if value.get("schema_version") != KEYWORD_FALLBACK_SCHEMA_VERSION or value.get("status") != "passed":
            errors.append(f"{path.name}: cache status or schema mismatch")
        if value.get("prompt_schema") != KEYWORD_PROMPT_SCHEMA:
            errors.append(f"{path.name}: prompt schema mismatch")
        cache_key = value.get("cache_key")
        if not isinstance(cache_key, str) or not re.fullmatch(r"[0-9a-f]{64}", cache_key) or path.stem != cache_key:
            errors.append(f"{path.name}: cache key mismatch")
        input_hash = value.get("input_hash")
        if not isinstance(input_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", input_hash):
            errors.append(f"{path.name}: input hash is invalid")
        for name in ("provider", "model", "version"):
            try:
                _machine_token(value.get(name), name)
            except CkbError as exc:
                errors.append(f"{path.name}: {exc}")
        serialized = json.dumps(value, ensure_ascii=False)
        if _CREDENTIAL_SHAPE.search(serialized):
            errors.append(f"{path.name}: cache contains credential-shaped text")
    unexpected = [path.name for path in root.iterdir() if not path.is_file() or path.suffix != ".json"]
    errors.extend(f"unexpected keyword cache entry: {name}" for name in sorted(unexpected))
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "records": records,
        "errors": errors,
    }


def write_keyword_fallback_record(
    output: Path,
    question: str,
    metadata: dict[str, Any],
) -> Path:
    """Persist one bounded request record without the raw question or provider output."""

    input_hash = keyword_input_hash(question)
    provider = str((metadata.get("provider") or {}).get("provider") or "unknown")
    model = str((metadata.get("provider") or {}).get("model") or "unknown")
    version = str((metadata.get("provider") or {}).get("version") or "unknown")
    identity = hashlib.sha256(
        json.dumps(
            {
                "input_hash": input_hash,
                "provider": provider,
                "model": model,
                "version": version,
                "prompt_schema": KEYWORD_PROMPT_SCHEMA,
                "trigger": metadata.get("trigger"),
            },
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    record = {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": metadata.get("status"),
        "input_hash": input_hash,
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
        "trigger": metadata.get("trigger"),
        "original": metadata.get("original"),
        "provider": metadata.get("provider"),
        "model_candidates": metadata.get("model_candidates"),
        "validated_extensions": metadata.get("validated_extensions"),
        "final": metadata.get("final"),
    }
    path = output.resolve() / "workspace-meta" / "keyword-fallback" / "requests" / f"{identity}.json"
    json_write(path, record)
    return path


def audit_keyword_fallback(output: Path) -> dict[str, Any]:
    """Audit cache and request records while enforcing the privacy boundary."""

    output = output.resolve()
    cache = audit_keyword_cache(output)
    root = output / "workspace-meta" / "keyword-fallback" / "requests"
    errors = [f"cache: {error}" for error in cache.get("errors", [])]
    records = 0
    if root.is_dir():
        unexpected = [path.name for path in root.iterdir() if not path.is_file() or path.suffix != ".json"]
        errors.extend(f"unexpected keyword request entry: {name}" for name in sorted(unexpected))
        for path in sorted(root.glob("*.json")):
            records += 1
            try:
                value = json_load(path)
            except (OSError, ValueError) as exc:
                errors.append(f"{path.name}: invalid request JSON: {type(exc).__name__}")
                continue
            if not isinstance(value, dict) or set(value) != _REQUEST_FIELDS:
                errors.append(f"{path.name}: fields differ from the fixed request schema")
                continue
            if value.get("schema_version") != KEYWORD_FALLBACK_SCHEMA_VERSION:
                errors.append(f"{path.name}: request schema mismatch")
            if value.get("status") not in {"passed", "fallback", "skipped", "no-quality-gain"}:
                errors.append(f"{path.name}: request status is invalid")
            if value.get("prompt_schema") != KEYWORD_PROMPT_SCHEMA:
                errors.append(f"{path.name}: prompt schema mismatch")
            if value.get("trigger") not in {"forced", "needs-source-read"}:
                errors.append(f"{path.name}: trigger is invalid")
            input_hash = value.get("input_hash")
            if not isinstance(input_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", input_hash):
                errors.append(f"{path.name}: input hash is invalid")
            provider = value.get("provider")
            if not isinstance(provider, dict):
                errors.append(f"{path.name}: provider summary must be an object")
                continue
            for name in ("provider", "model", "version"):
                try:
                    _machine_token(provider.get(name), name)
                except CkbError as exc:
                    errors.append(f"{path.name}: {exc}")
            expected_name = hashlib.sha256(
                json.dumps(
                    {
                        "input_hash": input_hash,
                        "provider": provider.get("provider"),
                        "model": provider.get("model"),
                        "version": provider.get("version"),
                        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
                        "trigger": value.get("trigger"),
                    },
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            if path.stem != expected_name:
                errors.append(f"{path.name}: request identity mismatch")
            serialized = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
            if re.search(r'"(?:question|prompt|command|stdout|stderr|secret|credential)"\s*:', serialized, re.IGNORECASE):
                errors.append(f"{path.name}: request record crosses the privacy boundary")
            if _CREDENTIAL_SHAPE.search(serialized):
                errors.append(f"{path.name}: request record contains credential-shaped text")
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "cache_records": cache.get("records", 0),
        "request_records": records,
        "errors": errors,
    }


def unique_casefold(values: Sequence[str]) -> list[str]:
    result: list[str] = []
    seen: set[str] = set()
    for value in values:
        normalized = value.strip()
        identity = normalized.casefold()
        if normalized and identity not in seen:
            seen.add(identity)
            result.append(normalized)
    return result

