            "appendix",
        ],
        "aggregate_page_sections": [
            "overview",
            "related_code",
            "backlinks",
            "tests",
            "hidden_relation_hint",
        ],
        "boundary_page_sections": [
            "overview",
            "boundary_details",
            "related_code",
            "backlinks",
            "hidden_relation_hint",
