            "boundary_details": "本次未继续展开的代码",
            "related_code": "相关代码",
            "backlinks": "谁会来到这里",
            "tests": "相关测试",
            "appendix": "内部细节",
        },
    },
    "relation_limits": {
        "direct": 20,
        "aggregate": 10,
        "test": 8,
        "boundary": 8,
    },
    "context": {
        "module_max_tokens": 80_000,
        "task_max_tokens": 20_000,
